        case CTEX_CHANNEL_SEMANTIC_HEIGHT:
            return ctex::image::ChannelSemantic::height;
        case CTEX_CHANNEL_SEMANTIC_OCCLUSION:
            return ctex::image::ChannelSemantic::occlusion;
        case CTEX_CHANNEL_SEMANTIC_EMISSION:
