ctex::paint::ParticleSettings paint_particle_settings(
    const ctex_paint_particle_settings& settings) {
    return {.count = settings.count,
            .lifetime_seconds = settings.lifetime_seconds,
            .initial_speed = settings.initial_speed,
            .mass = settings.mass,
            .gravity = stroke_vec(settings.gravity),
            .friction = settings.friction,
            .restitution = settings.restitution,
            .randomness = settings.randomness,
            .seed = settings.seed};
}

ctex_paint_particle_settings capi_particle_settings(const ctex::paint::ParticleSettings& settings) {
    return {.count = settings.count,
            .lifetime_seconds = settings.lifetime_seconds,
            .initial_speed = settings.initial_speed,
            .mass = settings.mass,
            .gravity = {settings.gravity.x, settings.gravity.y, settings.gravity.z},
            .friction = settings.friction,
            .restitution = settings.restitution,
            .randomness = settings.randomness,
            .seed = settings.seed};
}

std::size_t paint_particle_texture_set_id_size(
    std::span<const ctex::paint::ParticleContact> contacts) {
    std::size_t result = 0;
    for (const ctex::paint::ParticleContact& contact : contacts) {
        if (contact.texture_set_id.size() + 1 > std::numeric_limits<std::size_t>::max() - result) {
            throw std::overflow_error("particle texture-set ID buffer size overflow");
        }
        result += contact.texture_set_id.size() + 1;
    }
    return result;
}

void validate_paint_particle_outputs(const ctex_paint_particle_outputs* outputs,
                                     const ctex::paint::ParticleResult& result,
                                     std::size_t pixel_count, std::size_t texture_set_id_size) {
    if (outputs == nullptr) {
        return;
    }
    validate_structure_size(outputs->size, CTEX_PAINT_PARTICLE_OUTPUTS_V1_SIZE,
                            CTEX_PAINT_PARTICLE_OUTPUTS_CURRENT_SIZE, "outputs.size");
    validate_output_array(outputs->contacts, outputs->contact_capacity,
                          result.simulation.contacts.size(), "outputs.contacts");
    validate_output_array(outputs->final_states, outputs->final_state_capacity,
                          result.simulation.final_states.size(), "outputs.final_states");
    validate_output_array(outputs->texture_set_ids, outputs->texture_set_id_size,
                          texture_set_id_size, "outputs.texture_set_ids");
    validate_output_array(outputs->strength, outputs->strength_capacity, pixel_count,
                          "outputs.strength");
    validate_paint_tool_outputs(outputs->channels, outputs->channel_count, result.channels.size(),
                                pixel_count);
}

bool paint_particle_outputs_ready(const ctex_paint_particle_outputs& outputs,
                                  const ctex::paint::ParticleResult& result,
                                  std::size_t texture_set_id_size) {
    if ((!result.simulation.contacts.empty() && outputs.contacts == nullptr) ||
        (!result.simulation.final_states.empty() && outputs.final_states == nullptr) ||
        (texture_set_id_size != 0 && outputs.texture_set_ids == nullptr) ||
        (!result.strength.empty() && outputs.strength == nullptr) ||
        (!result.channels.empty() && outputs.channels == nullptr)) {
        return false;
    }
    for (std::size_t channel = 0; channel < result.channels.size(); ++channel) {
        if (outputs.channels[channel].pixels == nullptr) {
            return false;
        }
    }
    return true;
}

void copy_paint_particle_outputs(const ctex_paint_particle_outputs* outputs,
                                 const ctex::paint::ParticleResult& result,
                                 std::size_t texture_set_id_size) {
    if (outputs == nullptr ||
        !paint_particle_outputs_ready(*outputs, result, texture_set_id_size)) {
        return;
    }
    std::size_t texture_set_offset = 0;
    for (std::size_t index = 0; index < result.simulation.contacts.size(); ++index) {
        const ctex::paint::ParticleContact& source = result.simulation.contacts[index];
        outputs->contacts[index] = {
            .particle_ordinal = source.particle_ordinal,
            .collision_ordinal = source.collision_ordinal,
            .time_seconds = source.time_seconds,
            .position = {source.position.x, source.position.y, source.position.z},
            .normal = {source.normal.x, source.normal.y, source.normal.z},
            .uv = {source.uv.x, source.uv.y},
            .triangle = source.triangle,
            .impact_speed = source.impact_speed,
            .impulse = source.impulse,
            .strength = source.strength,
            .texture_set_id_offset = texture_set_offset,
            .texture_set_id_size = source.texture_set_id.size() + 1,
            .mapped_texel = result.contact_texels[index],
        };
        std::memcpy(outputs->texture_set_ids + texture_set_offset, source.texture_set_id.c_str(),
                    source.texture_set_id.size() + 1);
        texture_set_offset += source.texture_set_id.size() + 1;
    }
    for (std::size_t index = 0; index < result.simulation.final_states.size(); ++index) {
        const ctex::paint::ParticleState& source = result.simulation.final_states[index];
        outputs->final_states[index] = {
            .position = {source.position.x, source.position.y, source.position.z},
            .velocity = {source.velocity.x, source.velocity.y, source.velocity.z},
            .simulated_seconds = source.simulated_seconds,
            .collision_count = source.collision_count,
            .resting = source.resting,
        };
    }
    std::copy(result.strength.begin(), result.strength.end(), outputs->strength);
    copy_paint_tool_outputs(result.channels, outputs->channels);
}

void set_paint_particle_info(ctex_paint_particle_info& info,
                             const ctex::paint::ParticleResult& result,
                             std::size_t texture_set_id_size, std::size_t pixel_count) {
    const ctex::paint::ToolParameterReport& report = result.simulation.parameter_report;
    info = {
        .size = CTEX_PAINT_PARTICLE_INFO_CURRENT_SIZE,
        .resolved_settings = capi_particle_settings(result.simulation.resolved_settings),
        .count_clamped = report.clamp_for(ctex::paint::particle_count_parameter.name).has_value(),
        .lifetime_clamped =
            report.clamp_for(ctex::paint::particle_lifetime_parameter.name).has_value(),
        .initial_speed_clamped =
            report.clamp_for(ctex::paint::particle_initial_speed_parameter.name).has_value(),
        .mass_clamped = report.clamp_for(ctex::paint::particle_mass_parameter.name).has_value(),
        .gravity_x_clamped =
            report.clamp_for(ctex::paint::particle_gravity_x_parameter.name).has_value(),
        .gravity_y_clamped =
            report.clamp_for(ctex::paint::particle_gravity_y_parameter.name).has_value(),
        .gravity_z_clamped =
            report.clamp_for(ctex::paint::particle_gravity_z_parameter.name).has_value(),
        .friction_clamped =
            report.clamp_for(ctex::paint::particle_friction_parameter.name).has_value(),
        .restitution_clamped =
            report.clamp_for(ctex::paint::particle_restitution_parameter.name).has_value(),
        .randomness_clamped =
            report.clamp_for(ctex::paint::particle_randomness_parameter.name).has_value(),
        .emitted_count = result.simulation.emitted_count,
        .mapped_contact_count = result.mapped_contact_count,
        .applied_channel_count = result.channels.size(),
        .required_contact_count = result.simulation.contacts.size(),
        .required_final_state_count = result.simulation.final_states.size(),
        .required_texture_set_id_size = texture_set_id_size,
        .required_pixels_per_channel = pixel_count,
    };
}

std::size_t validate_paint_particle_call(ctex_pick_index* index,
                                         const ctex_paint_particle_descriptor* descriptor,
                                         const ctex_paint_particle_info* out_info) {
    if (index == nullptr || descriptor == nullptr || out_info == nullptr) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "index, descriptor and out_info are required");
    }
    validate_structure_size(descriptor->size, CTEX_PAINT_PARTICLE_DESCRIPTOR_V1_SIZE,
                            CTEX_PAINT_PARTICLE_DESCRIPTOR_CURRENT_SIZE, "descriptor.size");
    validate_structure_size(out_info->size, CTEX_PAINT_PARTICLE_INFO_V1_SIZE,
                            CTEX_PAINT_PARTICLE_INFO_CURRENT_SIZE, "out_info.size");
    if (descriptor->blend_mode == nullptr) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "blend_mode=null");
    }
    return bounded_paint_pixel_count(descriptor->width, descriptor->height,
                                     CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL);
}

struct PaintPickerViewStorage {
    std::string_view texture_set_id;
    ctex::paint::Vec2d tile_origin;
    std::uint32_t width{};
    std::uint32_t height{};
    std::vector<ctex::paint::PaintToolChannelRaster> channels;
    std::vector<std::string_view> material_identities;
    bool has_material_provenance{};
};

struct PaintPickerViews {
    std::vector<PaintPickerViewStorage> storage;
    std::vector<ctex::paint::PickerTextureView> views;
};

PaintPickerViewStorage paint_picker_view_storage(
    const ctex_paint_picker_texture_view_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_PAINT_PICKER_TEXTURE_VIEW_DESCRIPTOR_V1_SIZE,
                            CTEX_PAINT_PICKER_TEXTURE_VIEW_DESCRIPTOR_CURRENT_SIZE,
                            "texture_views.size");
    if (descriptor.texture_set_id == nullptr) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "texture_views.texture_set_id=null");
    }
    const std::size_t pixel_count = bounded_paint_pixel_count(descriptor.width, descriptor.height,
                                                              CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL);
    PaintPickerViewStorage result{
        .texture_set_id = descriptor.texture_set_id,
        .tile_origin = {descriptor.tile_origin.x, descriptor.tile_origin.y},
        .width = descriptor.width,
        .height = descriptor.height,
        .channels =
            paint_tool_channels(descriptor.enabled_channels, descriptor.enabled_channel_count,
                                pixel_count, "texture_views.enabled_channels"),
        .material_identities = {},
        .has_material_provenance = descriptor.material_identities != nullptr,
    };
    require_paint_tool_array(descriptor.material_identities, descriptor.material_identity_count,
                             "texture_views.material_identities");
    result.material_identities.reserve(descriptor.material_identity_count);
    for (std::size_t index = 0; index < descriptor.material_identity_count; ++index) {
        if (descriptor.material_identities[index] == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           "texture_views.material_identities entry is null");
        }
        result.material_identities.emplace_back(descriptor.material_identities[index]);
    }
    return result;
}

PaintPickerViews paint_picker_views(const ctex_paint_picker_texture_view_descriptor* descriptors,
                                    std::size_t count) {
    require_paint_tool_array(descriptors, count, "texture_views");
    PaintPickerViews result;
    result.storage.reserve(count);
    result.views.reserve(count);
    for (std::size_t index = 0; index < count; ++index) {
        result.storage.push_back(paint_picker_view_storage(descriptors[index]));
    }
    for (const PaintPickerViewStorage& source : result.storage) {
        std::optional<ctex::paint::MaterialProvenanceView> provenance;
        if (source.has_material_provenance) {
            provenance = ctex::paint::MaterialProvenanceView{source.material_identities};
        }
        result.views.push_back({.texture_set_id = source.texture_set_id,
                                .tile_origin = source.tile_origin,
                                .width = source.width,
                                .height = source.height,
                                .enabled_channels = source.channels,
                                .material_provenance = provenance});
    }
    return result;
}

ctex::pick::HitRecord paint_picker_hit(const ctex_paint_picker_descriptor& descriptor) {
    if (descriptor.hit_texture_set_id == nullptr) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "hit_texture_set_id=null");
    }
    if (descriptor.hit.has_hit == 0) {
        throw std::invalid_argument("picker requires a surface hit");
    }
    const ctex_pick_hit& hit = descriptor.hit;
    return {.position = {hit.position.x, hit.position.y, hit.position.z},
            .interpolated_normal = {hit.interpolated_normal.x, hit.interpolated_normal.y,
                                    hit.interpolated_normal.z},
            .geometric_normal = {hit.geometric_normal.x, hit.geometric_normal.y,
                                 hit.geometric_normal.z},
            .uv = {hit.uv.x, hit.uv.y},
            .texture_set_id = descriptor.hit_texture_set_id,
            .udim_tile = {hit.udim_u, hit.udim_v, hit.udim_number},
            .triangle_index = hit.triangle_index,
            .barycentric = {hit.barycentric.x, hit.barycentric.y, hit.barycentric.z},
            .material_id = hit.material_id,
            .distance = hit.distance};
}

std::vector<std::string> paint_picker_strings(const ctex::paint::PickerResult& result) {
    std::vector<std::string> strings;
    strings.reserve(result.channels.size() + (result.material_identity.has_value() ? 2 : 1));
    strings.push_back(result.texture_set_id);
    if (result.material_identity) {
        strings.push_back(*result.material_identity);
    }
    for (const ctex::paint::PickedChannelValue& channel : result.channels) {
        strings.push_back(channel.semantic_id);
    }
    return strings;
}

void set_paint_picker_info(ctex_paint_picker_info& info, const ctex::paint::PickerResult& result,
                           const std::vector<std::string>& strings,
                           std::size_t required_string_size) {
    const std::size_t texture_set_id_size = strings.front().size() + 1;
    const std::size_t material_identity_size = result.material_identity ? strings[1].size() + 1 : 0;
    info = {.size = CTEX_PAINT_PICKER_INFO_CURRENT_SIZE,
            .tile_origin = {result.tile_origin.x, result.tile_origin.y},
            .uv = {result.uv.x, result.uv.y},
            .texel = result.texel,
            .has_material_identity = result.material_identity.has_value(),
            .texture_set_id_offset = 0,
            .texture_set_id_size = texture_set_id_size,
            .material_identity_offset = result.material_identity ? texture_set_id_size : 0,
            .material_identity_size = material_identity_size,
            .required_channel_count = result.channels.size(),
            .required_string_size = required_string_size};
}

void copy_paint_picker_outputs(const ctex::paint::PickerResult& result,
                               const std::vector<std::string>& strings,
                               ctex_paint_picker_channel_value* channels, char* output_strings) {
    if (channels == nullptr || output_strings == nullptr) {
        return;
    }
    copy_packed_strings(strings, output_strings);
    std::size_t string_offset = strings.front().size() + 1;
    std::size_t string_index = 1;
    if (result.material_identity) {
        string_offset += strings[string_index].size() + 1;
        ++string_index;
    }
    for (std::size_t index = 0; index < result.channels.size(); ++index, ++string_index) {
        const ctex::paint::PickedChannelValue& source = result.channels[index];
        channels[index] = {.component_count = source.component_count,
                           .value = capi_colour(source.value),
                           .semantic_id_offset = string_offset,
                           .semantic_id_size = strings[string_index].size() + 1};
        string_offset += strings[string_index].size() + 1;
    }
}

std::vector<ctex::graph::ColourValue> paint_colour_id_pixels(
    const ctex_paint_colour_id_descriptor& descriptor, std::size_t pixel_count) {
    require_paint_tool_array(descriptor.pixels, descriptor.pixel_count, "pixels");
    if (descriptor.pixel_count != pixel_count) {
        throw std::invalid_argument("colour-ID pixel count does not match its dimensions");
    }
    std::vector<ctex::graph::ColourValue> result;
    result.reserve(pixel_count);
    for (std::size_t index = 0; index < pixel_count; ++index) {
        result.push_back(paint_colour(descriptor.pixels[index]));
    }
    return result;
}

void set_paint_colour_id_info(ctex_paint_colour_id_info& info,
                              const ctex::paint::ColourIdSelection& selection) {
    info = {
        .size = CTEX_PAINT_COLOUR_ID_INFO_CURRENT_SIZE,
        .resolved_tolerance = selection.tolerance,
        .tolerance_clamped =
            selection.parameter_report.clamp_for(ctex::paint::colour_id_tolerance_parameter.name)
                .has_value(),
        .status = selection.status == ctex::paint::ColourIdSelectionStatus::matched
                      ? CTEX_PAINT_COLOUR_ID_SELECTION_MATCHED
                      : CTEX_PAINT_COLOUR_ID_SELECTION_EMPTY,
        .selected_texel_count = selection.selected_texel_count,
        .required_value_count = selection.values.size(),
    };
}

