struct PreparedShaderEmission {
    ctex::emit::MaterialShaderEmission value;
    std::vector<std::byte> vertex;
    std::vector<std::byte> fragment;
    std::string pass_plan;
    std::string workarounds;
    std::string debug_metadata;
};

std::vector<std::byte> shader_text_artifact(std::string_view source) {
    std::vector<std::byte> output(source.size() + 1);
    std::memcpy(output.data(), source.data(), source.size());
    output.back() = std::byte{};
    return output;
}

void prepare_shader_artifacts(const ctex::emit::KongShaderProgram& shader,
                              std::vector<std::byte>& vertex, std::vector<std::byte>& fragment) {
    std::visit(
        [&](const auto& payload) {
            using Payload = std::decay_t<decltype(payload)>;
            if constexpr (std::is_same_v<Payload, ctex::emit::SplitTextShaderProgram>) {
                vertex = shader_text_artifact(payload.vertex_source);
                fragment = shader_text_artifact(payload.fragment_source);
            } else if constexpr (std::is_same_v<Payload, ctex::emit::UnifiedTextShaderProgram>) {
                vertex = shader_text_artifact(payload.source);
            } else {
                vertex.resize(payload.vertex_module.size() * sizeof(std::uint32_t));
                fragment.resize(payload.fragment_module.size() * sizeof(std::uint32_t));
                std::memcpy(vertex.data(), payload.vertex_module.data(), vertex.size());
                std::memcpy(fragment.data(), payload.fragment_module.data(), fragment.size());
            }
        },
        shader.payload);
}

PreparedShaderEmission prepare_shader_emission(ctex::emit::MaterialShaderEmission emission) {
    PreparedShaderEmission result{.value = std::move(emission),
                                  .vertex = {},
                                  .fragment = {},
                                  .pass_plan = {},
                                  .workarounds = {},
                                  .debug_metadata = {}};
    prepare_shader_artifacts(result.value.shader, result.vertex, result.fragment);
    result.pass_plan = shader_pass_plan_json(result.value.pass_plan);
    result.workarounds = shader_workaround_json(result.value.workarounds);
    result.debug_metadata = shader_debug_metadata_json(result.value);
    return result;
}

std::size_t shader_binding_count(const ctex::emit::PassPlan& plan) {
    std::size_t result = 0;
    for (const ctex::emit::PassDescriptor& pass : plan.passes()) {
        result += pass.texture_bindings.size() + pass.sampler_bindings.size() +
                  pass.uniform_blocks.size();
    }
    return result;
}

void return_shader_material_emission(const PreparedShaderEmission& prepared, std::uint32_t target,
                                     ctex_shader_material_info* out_info, void* vertex_artifact,
                                     std::size_t vertex_artifact_size, void* fragment_artifact,
                                     std::size_t fragment_artifact_size, char* pass_plan_output,
                                     std::size_t pass_plan_output_size,
                                     char* workaround_report_output,
                                     std::size_t workaround_report_output_size) {
    *out_info = {
        .size = CTEX_SHADER_MATERIAL_INFO_CURRENT_SIZE,
        .target = target,
        .vertex_artifact_size = prepared.vertex.size(),
        .fragment_artifact_size = prepared.fragment.size(),
        .pass_plan_size = prepared.pass_plan.size() + 1,
        .workaround_report_size = prepared.workarounds.size() + 1,
        .pass_count = prepared.value.pass_plan.passes().size(),
        .logical_resource_count = prepared.value.pass_plan.resources().size(),
        .binding_count = shader_binding_count(prepared.value.pass_plan),
        .workaround_count = prepared.value.workarounds.size(),
    };
    validate_output_array(vertex_artifact, vertex_artifact_size, prepared.vertex.size(),
                          "vertex_artifact");
    validate_output_array(fragment_artifact, fragment_artifact_size, prepared.fragment.size(),
                          "fragment_artifact");
    validate_string_buffer(pass_plan_output, pass_plan_output_size, out_info->pass_plan_size);
    validate_string_buffer(workaround_report_output, workaround_report_output_size,
                           out_info->workaround_report_size);
    if (vertex_artifact != nullptr && !prepared.vertex.empty()) {
        std::memcpy(vertex_artifact, prepared.vertex.data(), prepared.vertex.size());
    }
    if (fragment_artifact != nullptr && !prepared.fragment.empty()) {
        std::memcpy(fragment_artifact, prepared.fragment.data(), prepared.fragment.size());
    }
    if (pass_plan_output != nullptr) {
        std::memcpy(pass_plan_output, prepared.pass_plan.c_str(), out_info->pass_plan_size);
    }
    if (workaround_report_output != nullptr) {
        std::memcpy(workaround_report_output, prepared.workarounds.c_str(),
                    out_info->workaround_report_size);
    }
}

void return_inspectable_material_emission(
    const PreparedShaderEmission& prepared, std::uint32_t target, bool cache_hit,
    ctex_shader_material_info* out_info, void* vertex_artifact, std::size_t vertex_artifact_size,
    void* fragment_artifact, std::size_t fragment_artifact_size, char* pass_plan_output,
    std::size_t pass_plan_output_size, char* workaround_report_output,
    std::size_t workaround_report_output_size, ctex_shader_material_debug_info* out_debug_info,
    char* debug_metadata_output, std::size_t debug_metadata_output_size,
    std::uint32_t* out_cache_hit) {
    *out_debug_info = {
        .size = CTEX_SHADER_MATERIAL_DEBUG_INFO_CURRENT_SIZE,
        .node_attribution_count = prepared.value.node_attributions.size(),
        .metadata_size = prepared.debug_metadata.size() + 1,
        .binary_companion =
            prepared.value.shader.target == ctex::emit::ShaderTarget::spirv ? 1U : 0U,
    };
    validate_string_buffer(debug_metadata_output, debug_metadata_output_size,
                           out_debug_info->metadata_size);
    return_shader_material_emission(prepared, target, out_info, vertex_artifact,
                                    vertex_artifact_size, fragment_artifact, fragment_artifact_size,
                                    pass_plan_output, pass_plan_output_size,
                                    workaround_report_output, workaround_report_output_size);
    if (debug_metadata_output != nullptr) {
        std::memcpy(debug_metadata_output, prepared.debug_metadata.c_str(),
                    out_debug_info->metadata_size);
    }
    *out_cache_hit = cache_hit ? 1U : 0U;
}

PreparedShaderEmission emit_material_source(
    ctex_shader_emission_cache* cache, const ctex_material_graph_node_registry* registry,
    const ctex_shader_material_source_descriptor& source,
    const ctex::emit::MaterialShaderEmissionRequest& request, bool& cache_hit) {
    validate_structure_size(source.size, CTEX_SHADER_MATERIAL_SOURCE_DESCRIPTOR_V1_SIZE,
                            CTEX_SHADER_MATERIAL_SOURCE_DESCRIPTOR_CURRENT_SIZE,
                            "shader material source size");
    if (source.kind == CTEX_SHADER_MATERIAL_SOURCE_SERIALIZED_GRAPH) {
        if (source.workspace != nullptr || source.material_identifier != nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_SHADER_EMISSION,
                           "serialized graph source also contains workspace fields");
        }
        const ctex::graph::GraphDocument graph = ctex::graph::deserialize_graph(
            material_graph_bytes(source.graph_serialized, source.graph_serialized_size));
        if (cache == nullptr) {
            cache_hit = false;
            return prepare_shader_emission(
                registry == nullptr
                    ? ctex::emit::emit_material_shader(graph, request)
                    : ctex::emit::emit_material_shader(graph, registry->value, request));
        }
        const ctex::emit::CachedMaterialShaderEmission cached =
            registry == nullptr ? cache->material.emit(graph, request)
                                : cache->material.emit(graph, registry->value, request);
        cache_hit = cached.cache_hit;
        return prepare_shader_emission(*cached.emission);
    }
    if (source.kind != CTEX_SHADER_MATERIAL_SOURCE_WORKSPACE) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_ENUM_VALUE,
                       "shader material source kind=" + std::to_string(source.kind));
    }
    if (source.workspace == nullptr || source.material_identifier == nullptr) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "workspace and material_identifier are required");
    }
    if (source.graph_serialized != nullptr || source.graph_serialized_size != 0) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_SHADER_EMISSION,
                       "workspace source also contains serialized graph fields");
    }
    if (cache == nullptr) {
        cache_hit = false;
        return prepare_shader_emission(
            registry == nullptr ? ctex::emit::emit_workspace_material_shader(
                                      source.workspace->value, source.material_identifier, request)
                                : ctex::emit::emit_workspace_material_shader(
                                      source.workspace->value, source.material_identifier,
                                      registry->value, request));
    }
    const ctex::emit::CachedMaterialShaderEmission cached =
        registry == nullptr
            ? cache->material.emit_material(source.workspace->value, source.material_identifier,
                                            request)
            : cache->material.emit_material(source.workspace->value, source.material_identifier,
                                            registry->value, request);
    cache_hit = cached.cache_hit;
    return prepare_shader_emission(*cached.emission);
}

struct PreparedPreviewEmission {
    ctex::emit::PreviewEmission value;
    std::vector<std::byte> vertex;
    std::vector<std::byte> fragment;
    std::string pass_plan;
    std::string workarounds;
};

PreparedPreviewEmission prepare_preview_emission(ctex::emit::PreviewEmission emission) {
    PreparedPreviewEmission result{.value = std::move(emission),
                                   .vertex = {},
                                   .fragment = {},
                                   .pass_plan = {},
                                   .workarounds = {}};
    prepare_shader_artifacts(result.value.shader, result.vertex, result.fragment);
    result.pass_plan = shader_pass_plan_json(result.value.pass_plan);
    result.workarounds = shader_workaround_json(result.value.workarounds);
    return result;
}

void return_preview_emission(const PreparedPreviewEmission& prepared, bool cache_hit,
                             ctex_shader_preview_info* out_info, void* vertex_artifact,
                             std::size_t vertex_artifact_size, void* fragment_artifact,
                             std::size_t fragment_artifact_size, char* pass_plan_output,
                             std::size_t pass_plan_output_size, char* workaround_report_output,
                             std::size_t workaround_report_output_size) {
    *out_info = {
        .size = CTEX_SHADER_PREVIEW_INFO_CURRENT_SIZE,
        .target = static_cast<std::uint32_t>(prepared.value.shader.target),
        .kind = static_cast<std::uint32_t>(prepared.value.kind),
        .fallback_lighting = prepared.value.fallback_lighting ? 1U : 0U,
        .cache_hit = cache_hit ? 1U : 0U,
        .vertex_artifact_size = prepared.vertex.size(),
        .fragment_artifact_size = prepared.fragment.size(),
        .pass_plan_size = prepared.pass_plan.size() + 1,
        .workaround_report_size = prepared.workarounds.size() + 1,
        .pass_count = prepared.value.pass_plan.passes().size(),
        .logical_resource_count = prepared.value.pass_plan.resources().size(),
        .binding_count = shader_binding_count(prepared.value.pass_plan),
        .workaround_count = prepared.value.workarounds.size(),
    };
    validate_output_array(vertex_artifact, vertex_artifact_size, prepared.vertex.size(),
                          "vertex_artifact");
    validate_output_array(fragment_artifact, fragment_artifact_size, prepared.fragment.size(),
                          "fragment_artifact");
    validate_string_buffer(pass_plan_output, pass_plan_output_size, out_info->pass_plan_size);
    validate_string_buffer(workaround_report_output, workaround_report_output_size,
                           out_info->workaround_report_size);
    if (vertex_artifact != nullptr && !prepared.vertex.empty()) {
        std::memcpy(vertex_artifact, prepared.vertex.data(), prepared.vertex.size());
    }
    if (fragment_artifact != nullptr && !prepared.fragment.empty()) {
        std::memcpy(fragment_artifact, prepared.fragment.data(), prepared.fragment.size());
    }
    if (pass_plan_output != nullptr) {
        std::memcpy(pass_plan_output, prepared.pass_plan.c_str(), out_info->pass_plan_size);
    }
    if (workaround_report_output != nullptr) {
        std::memcpy(workaround_report_output, prepared.workarounds.c_str(),
                    out_info->workaround_report_size);
    }
}

PreparedPreviewEmission emit_preview_request(ctex_shader_emission_cache* cache,
                                             const ctex::emit::PreviewEmissionRequest& request,
                                             std::optional<std::string_view> inspected_channel,
                                             bool& cache_hit) {
    if (cache == nullptr) {
        cache_hit = false;
        return prepare_preview_emission(
            inspected_channel.has_value()
                ? ctex::emit::emit_channel_inspection(request, *inspected_channel)
                : ctex::emit::emit_lit_preview(request));
    }
    const ctex::emit::CachedPreviewEmission cached =
        inspected_channel.has_value() ? cache->preview.emit_inspection(request, *inspected_channel)
                                      : cache->preview.emit_lit(request);
    cache_hit = cached.cache_hit;
    return prepare_preview_emission(*cached.emission);
}

struct PreparedLayerStackEmission {
    std::vector<std::byte> artifacts;
    std::string artifact_report;
    std::string pass_plan;
    std::string workarounds;
};

struct ShaderArtifactRange {
    std::size_t vertex_offset{};
    std::size_t vertex_size{};
    std::size_t fragment_offset{};
    std::size_t fragment_size{};
    const char* encoding{};
};

void append_shader_artifact(std::vector<std::byte>& destination,
                            std::span<const std::byte> artifact) {
    destination.insert(destination.end(), artifact.begin(), artifact.end());
}

ShaderArtifactRange append_shader_program(std::vector<std::byte>& destination,
                                          const ctex::emit::KongShaderProgram& program) {
    ShaderArtifactRange range{.vertex_offset = destination.size()};
    std::visit(
        [&](const auto& payload) {
            using Payload = std::decay_t<decltype(payload)>;
            if constexpr (std::is_same_v<Payload, ctex::emit::SplitTextShaderProgram>) {
                const auto vertex = shader_text_artifact(payload.vertex_source);
                const auto fragment = shader_text_artifact(payload.fragment_source);
                range.vertex_size = vertex.size();
                append_shader_artifact(destination, vertex);
                range.fragment_offset = destination.size();
                range.fragment_size = fragment.size();
                append_shader_artifact(destination, fragment);
                range.encoding = "text";
            } else if constexpr (std::is_same_v<Payload, ctex::emit::UnifiedTextShaderProgram>) {
                const auto source = shader_text_artifact(payload.source);
                range.vertex_size = source.size();
                append_shader_artifact(destination, source);
                range.fragment_offset = destination.size();
                range.encoding = "text";
            } else {
                range.vertex_size = payload.vertex_module.size() * sizeof(std::uint32_t);
                append_shader_artifact(
                    destination, {reinterpret_cast<const std::byte*>(payload.vertex_module.data()),
                                  range.vertex_size});
                range.fragment_offset = destination.size();
                range.fragment_size = payload.fragment_module.size() * sizeof(std::uint32_t);
                append_shader_artifact(
                    destination,
                    {reinterpret_cast<const std::byte*>(payload.fragment_module.data()),
                     range.fragment_size});
                range.encoding = "spirv";
            }
        },
        program.payload);
    return range;
}

PreparedLayerStackEmission prepare_layer_stack_emission(
    const ctex::emit::LayerStackEmission& emission) {
    PreparedLayerStackEmission result;
    result.artifact_report = "[";
    for (std::size_t index = 0; index < emission.shaders.size(); ++index) {
        const ctex::emit::EmittedLayerStackPass& shader = emission.shaders[index];
        const ShaderArtifactRange range = append_shader_program(result.artifacts, shader.shader);
        if (index != 0) result.artifact_report.push_back(',');
        result.artifact_report += "{\"pass_identifier\":";
        append_json_text(result.artifact_report, shader.pass_identifier);
        result.artifact_report += ",\"target\":";
        append_json_text(result.artifact_report,
                         ctex::emit::shader_target_name(shader.shader.target));
        result.artifact_report += ",\"encoding\":";
        append_json_text(result.artifact_report, range.encoding);
        result.artifact_report += ",\"vertex_offset\":" + std::to_string(range.vertex_offset) +
                                  ",\"vertex_size\":" + std::to_string(range.vertex_size) +
                                  ",\"fragment_offset\":" + std::to_string(range.fragment_offset) +
                                  ",\"fragment_size\":" + std::to_string(range.fragment_size) + "}";
    }
    result.artifact_report.push_back(']');
    result.pass_plan = shader_pass_plan_json(emission.pass_plan);
    result.workarounds = shader_workaround_json(emission.workarounds);
    return result;
}

void return_layer_stack_emission(const ctex::emit::LayerStackEmission& emission,
                                 const PreparedLayerStackEmission& prepared,
                                 const ctex_shader_layer_stack_request& request, bool cache_hit,
                                 ctex_shader_layer_stack_info* out_info, void* artifact_blob,
                                 std::size_t artifact_blob_size, char* artifact_report_output,
                                 std::size_t artifact_report_output_size, char* pass_plan_output,
                                 std::size_t pass_plan_output_size, char* workaround_report_output,
                                 std::size_t workaround_report_output_size) {
    *out_info = {
        .size = CTEX_SHADER_LAYER_STACK_INFO_CURRENT_SIZE,
        .target = request.target,
        .layer_count = request.layer_count,
        .pass_count = emission.pass_plan.passes().size(),
        .artifact_blob_size = prepared.artifacts.size(),
        .artifact_report_size = prepared.artifact_report.size() + 1,
        .pass_plan_size = prepared.pass_plan.size() + 1,
        .workaround_report_size = prepared.workarounds.size() + 1,
        .workaround_count = emission.workarounds.size(),
        .compute_used = emission.compute_used ? 1U : 0U,
        .cache_hit = cache_hit ? 1U : 0U,
    };
    validate_output_array(artifact_blob, artifact_blob_size, prepared.artifacts.size(),
                          "artifact_blob");
    validate_string_buffer(artifact_report_output, artifact_report_output_size,
                           out_info->artifact_report_size);
    validate_string_buffer(pass_plan_output, pass_plan_output_size, out_info->pass_plan_size);
    validate_string_buffer(workaround_report_output, workaround_report_output_size,
                           out_info->workaround_report_size);
    if (artifact_blob != nullptr && !prepared.artifacts.empty()) {
        std::memcpy(artifact_blob, prepared.artifacts.data(), prepared.artifacts.size());
    }
    if (artifact_report_output != nullptr) {
        std::memcpy(artifact_report_output, prepared.artifact_report.c_str(),
                    out_info->artifact_report_size);
    }
    if (pass_plan_output != nullptr) {
        std::memcpy(pass_plan_output, prepared.pass_plan.c_str(), out_info->pass_plan_size);
    }
    if (workaround_report_output != nullptr) {
        std::memcpy(workaround_report_output, prepared.workarounds.c_str(),
                    out_info->workaround_report_size);
    }
}

template <typename Operation>
ctex_result call_shader_emission_boundary(const char* name, Operation&& operation) noexcept {
    return call_boundary(name, [&] {
        try {
            operation();
        } catch (const ctex::emit::KongCompilationError& error) {
            throw_boundary(CTEX_RESULT_UNSUPPORTED_OPERATION,
                           CTEX_DIAGNOSTIC_INVALID_SHADER_EMISSION, error.what());
        } catch (const ctex::emit::GraphEmissionError& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_SHADER_EMISSION,
                           error.what());
        } catch (const ctex::emit::MaterialEmissionError& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_SHADER_EMISSION,
                           error.what());
        } catch (const std::invalid_argument& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_SHADER_EMISSION,
                           error.what());
        }
    });
}

const ctex::exec::ExecutorDescriptor& executor_at(const ctex_executor_registry& registry,
                                                  std::size_t index) {
    const ctex::exec::Executor* executor = nullptr;
    const auto descriptors = registry.value.enumerate();
    if (index >= descriptors.size()) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_EXECUTOR,
                       "executor index=" + std::to_string(index) +
                           " count=" + std::to_string(descriptors.size()));
    }
    executor = registry.value.find(descriptors[index].identifier);
    if (executor == nullptr) {
        throw std::logic_error("enumerated executor could not be resolved");
    }
    return executor->descriptor();
}

std::size_t executor_index(const ctex_executor_registry& registry, std::string_view identifier) {
    const auto descriptors = registry.value.enumerate();
    const auto found = std::find_if(descriptors.begin(), descriptors.end(), [&](const auto& value) {
        return value.identifier == identifier;
    });
    if (found == descriptors.end()) {
        throw std::logic_error("selected executor is absent from its registry");
    }
    return static_cast<std::size_t>(found - descriptors.begin());
}

void validate_executor_string(char* output, std::size_t output_size, const std::string& value) {
    validate_string_buffer(output, output_size, value.size() + 1);
}

void copy_executor_string(const std::string& value, char* output) {
    if (output != nullptr) {
        std::memcpy(output, value.c_str(), value.size() + 1);
    }
}

const char* require_executor_text(const char* value, std::string_view field) {
    if (value == nullptr) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       std::string(field) + "=null");
    }
    if (value[0] == '\0') {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_EXECUTOR,
                       std::string(field) + " is empty");
    }
    return value;
}

bool valid_callback_result(ctex_result result) {
    return result >= CTEX_RESULT_SUCCESS && result <= CTEX_RESULT_BUFFER_TOO_SMALL;
}

void require_successful_executor_callback(ctex_result result, std::string_view callback) {
    if (result == CTEX_RESULT_SUCCESS) {
        return;
    }
    if (!valid_callback_result(result)) {
        throw_boundary(CTEX_RESULT_INTERNAL_ERROR, CTEX_DIAGNOSTIC_INVALID_EXECUTOR,
                       std::string(callback) + " callback returned an invalid result code");
    }
    throw_boundary(result, CTEX_DIAGNOSTIC_INVALID_EXECUTOR,
                   std::string(callback) + " callback reported failure");
}

class CapiCpuBoundedOperation final : public ctex::exec::CpuBoundedOperation {
public:
    explicit CapiCpuBoundedOperation(const ctex_cpu_bounded_execution_descriptor& descriptor)
        : descriptor_(descriptor) {}

    [[nodiscard]] std::string_view identifier() const noexcept override {
        return descriptor_.operation;
    }

    [[nodiscard]] ctex::exec::CpuWorkPlan plan() const override {
        return {
            .work_item_count = descriptor_.work_item_count,
            .shared_working_memory_bytes = descriptor_.shared_working_memory_bytes,
            .working_memory_bytes_per_worker = descriptor_.working_memory_bytes_per_worker,
        };
    }

    void execute_work_item(const ctex::exec::CpuReferenceExecutor&, std::size_t work_item,
                           std::span<std::byte> shared,
                           std::span<std::byte> worker_memory) override {
        ctex_result result = CTEX_RESULT_INTERNAL_ERROR;
        try {
            result = descriptor_.execute_work_item(work_item, shared.data(), shared.size(),
                                                   worker_memory.data(), worker_memory.size(),
                                                   descriptor_.user_data);
        } catch (...) {
            throw_boundary(CTEX_RESULT_INTERNAL_ERROR, CTEX_DIAGNOSTIC_INVALID_EXECUTOR,
                           "execute_work_item callback threw an exception");
        }
        require_successful_executor_callback(result, "execute_work_item");
    }

    void commit(std::span<const std::byte> shared) noexcept override {
        try {
            commit_result_.store(
                descriptor_.commit(shared.data(), shared.size(), descriptor_.user_data),
                std::memory_order_relaxed);
        } catch (...) {
            callback_exception_.store(true, std::memory_order_relaxed);
        }
    }

    [[nodiscard]] ctex::exec::ExecutionControl control() noexcept {
        return {
            .maximum_workers = descriptor_.maximum_workers,
            .memory_ceiling_bytes = descriptor_.memory_ceiling_bytes,
            .progress_interval = descriptor_.progress_interval,
            .user_data = this,
            .is_cancelled = cancel_bridge,
            .report_progress = progress_bridge,
        };
    }

    void validate_callbacks() const {
        if (callback_exception_.load(std::memory_order_relaxed)) {
            throw_boundary(CTEX_RESULT_INTERNAL_ERROR, CTEX_DIAGNOSTIC_INVALID_EXECUTOR,
                           "CPU execution callback threw an exception");
        }
        require_successful_executor_callback(commit_result_.load(std::memory_order_relaxed),
                                             "commit");
    }

private:
    static bool cancel_bridge(void* user_data) noexcept {
        auto& operation = *static_cast<CapiCpuBoundedOperation*>(user_data);
        if (operation.callback_exception_.load(std::memory_order_relaxed)) {
            return true;
        }
        if (operation.descriptor_.is_cancelled == nullptr) {
            return false;
        }
        try {
            return operation.descriptor_.is_cancelled(operation.descriptor_.user_data) != 0;
        } catch (...) {
            operation.callback_exception_.store(true, std::memory_order_relaxed);
            return true;
        }
    }

    static void progress_bridge(void* user_data, ctex::exec::ExecutionProgress progress) noexcept {
        auto& operation = *static_cast<CapiCpuBoundedOperation*>(user_data);
        if (operation.descriptor_.report_progress == nullptr ||
            operation.callback_exception_.load(std::memory_order_relaxed)) {
            return;
        }
        try {
            operation.descriptor_.report_progress(progress.completed_work_items,
                                                  progress.total_work_items,
                                                  operation.descriptor_.user_data);
        } catch (...) {
            operation.callback_exception_.store(true, std::memory_order_relaxed);
        }
    }

    const ctex_cpu_bounded_execution_descriptor& descriptor_;
    std::atomic<ctex_result> commit_result_{CTEX_RESULT_SUCCESS};
    std::atomic_bool callback_exception_{};
};

void validate_cpu_bounded_execution_descriptor(
    const ctex_cpu_bounded_execution_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_CPU_BOUNDED_EXECUTION_DESCRIPTOR_V1_SIZE,
                            CTEX_CPU_BOUNDED_EXECUTION_DESCRIPTOR_CURRENT_SIZE,
                            "CPU bounded execution descriptor size");
    static_cast<void>(require_executor_text(descriptor.operation, "operation"));
    if (descriptor.execute_work_item == nullptr || descriptor.commit == nullptr) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "execute_work_item and commit callbacks are required");
    }
}

std::uint32_t cpu_execution_status(ctex::exec::ExecutionStatus status) {
    switch (status) {
        case ctex::exec::ExecutionStatus::completed:
            return CTEX_CPU_EXECUTION_COMPLETED;
        case ctex::exec::ExecutionStatus::cancelled:
            return CTEX_CPU_EXECUTION_CANCELLED;
        case ctex::exec::ExecutionStatus::memory_ceiling_exceeded:
            return CTEX_CPU_EXECUTION_MEMORY_CEILING_EXCEEDED;
    }
    throw std::logic_error("unknown CPU execution status");
}

struct CpuRasterMeshStorage {
    std::vector<ctex::exec::CpuVec3f> positions;
    std::vector<ctex::exec::CpuVec2f> uv;
    std::span<const std::uint32_t> triangle_indices;

    [[nodiscard]] ctex::exec::CpuRasterMeshView view() const noexcept {
        return {positions, uv, triangle_indices};
    }
};

CpuRasterMeshStorage cpu_raster_mesh(const ctex_cpu_raster_mesh_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_CPU_RASTER_MESH_DESCRIPTOR_V1_SIZE,
                            CTEX_CPU_RASTER_MESH_DESCRIPTOR_CURRENT_SIZE,
                            "CPU raster mesh descriptor size");
    if ((descriptor.positions == nullptr || descriptor.uv == nullptr) &&
        descriptor.vertex_count != 0) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "CPU raster positions and UVs are required for non-empty vertices");
    }
    if (descriptor.triangle_indices == nullptr && descriptor.triangle_index_count != 0) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "CPU raster triangle indices are required for non-empty triangles");
    }
    if (descriptor.vertex_count > CTEX_MAX_MESH_VERTEX_COUNT ||
        descriptor.triangle_index_count / 3 > CTEX_MAX_MESH_TRIANGLE_COUNT) {
        throw_boundary(CTEX_RESULT_OVER_BUDGET, CTEX_DIAGNOSTIC_INVALID_EXECUTOR,
                       "CPU raster mesh exceeds the public mesh limits");
    }
    CpuRasterMeshStorage result;
    result.positions.reserve(descriptor.vertex_count);
    result.uv.reserve(descriptor.vertex_count);
    for (std::size_t index = 0; index < descriptor.vertex_count; ++index) {
        result.positions.push_back({descriptor.positions[index].x, descriptor.positions[index].y,
                                    descriptor.positions[index].z});
        result.uv.push_back({descriptor.uv[index].x, descriptor.uv[index].y});
    }
    result.triangle_indices = descriptor.triangle_index_count == 0
                                  ? std::span<const std::uint32_t>{}
                                  : std::span<const std::uint32_t>{descriptor.triangle_indices,
                                                                   descriptor.triangle_index_count};
    return result;
}

ctex::exec::CpuRasterCamera cpu_raster_camera(const ctex_cpu_raster_camera_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_CPU_RASTER_CAMERA_DESCRIPTOR_V1_SIZE,
                            CTEX_CPU_RASTER_CAMERA_DESCRIPTOR_CURRENT_SIZE,
                            "CPU raster camera descriptor size");
    ctex::exec::CpuRasterCamera result{
        .view_projection = {}, .width = descriptor.width, .height = descriptor.height};
    std::copy(std::begin(descriptor.view_projection), std::end(descriptor.view_projection),
              result.view_projection.values.begin());
    return result;
}

std::size_t bounded_cpu_raster_pixel_count(std::uint32_t width, std::uint32_t height,
                                           std::size_t maximum_output_pixels) {
    if (width == 0 || height == 0 || maximum_output_pixels == 0) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_EXECUTOR,
                       "CPU raster dimensions and maximum_output_pixels must be non-zero");
    }
    if (static_cast<std::size_t>(width) >
        std::numeric_limits<std::size_t>::max() / static_cast<std::size_t>(height)) {
        throw_boundary(CTEX_RESULT_OVER_BUDGET, CTEX_DIAGNOSTIC_INVALID_EXECUTOR,
                       "CPU raster dimensions exceed addressable storage");
    }
    const std::size_t pixel_count = static_cast<std::size_t>(width) * height;
    if (pixel_count > maximum_output_pixels) {
        throw_boundary(CTEX_RESULT_OVER_BUDGET, CTEX_DIAGNOSTIC_INVALID_EXECUTOR,
                       "CPU raster pixel_count=" + std::to_string(pixel_count) +
                           " maximum_output_pixels=" + std::to_string(maximum_output_pixels));
    }
    return pixel_count;
}

void validate_cpu_raster_outputs(const ctex_cpu_raster_outputs* outputs, std::size_t pixel_count) {
    if (outputs == nullptr) {
        return;
    }
    validate_structure_size(outputs->size, CTEX_CPU_RASTER_OUTPUTS_V1_SIZE,
                            CTEX_CPU_RASTER_OUTPUTS_CURRENT_SIZE, "CPU raster outputs size");
    validate_output_array(outputs->depth, outputs->depth_capacity, pixel_count, "depth");
    validate_output_array(outputs->coordinates, outputs->coordinate_capacity, pixel_count,
                          "coordinates");
    validate_output_array(outputs->coverage, outputs->coverage_capacity, pixel_count, "coverage");
    validate_output_array(outputs->triangle_identity, outputs->triangle_identity_capacity,
                          pixel_count, "triangle_identity");
}

template <typename Raster>
void return_cpu_raster(const Raster& raster, std::span<const ctex::exec::CpuVec2f> coordinates,
                       ctex_cpu_raster_info& out_info, const ctex_cpu_raster_outputs* outputs) {
    const std::size_t pixel_count = raster.depth.size();
    out_info = {.size = CTEX_CPU_RASTER_INFO_CURRENT_SIZE,
                .width = raster.width,
                .height = raster.height,
                .pixel_count = pixel_count};
    validate_cpu_raster_outputs(outputs, pixel_count);
    if (outputs == nullptr) {
        return;
    }
    if (outputs->depth != nullptr) {
        std::copy(raster.depth.begin(), raster.depth.end(), outputs->depth);
    }
    if (outputs->coordinates != nullptr) {
        std::transform(coordinates.begin(), coordinates.end(), outputs->coordinates,
                       [](ctex::exec::CpuVec2f value) { return ctex_vec2f{value.x, value.y}; });
    }
    if (outputs->coverage != nullptr) {
        std::copy(raster.coverage.begin(), raster.coverage.end(), outputs->coverage);
    }
    if (outputs->triangle_identity != nullptr) {
        std::copy(raster.triangle.begin(), raster.triangle.end(), outputs->triangle_identity);
    }
}

ctex::exec::ParityValueClass parity_value_class(std::uint32_t value) {
    if (value > CTEX_PARITY_FLOATING_POINT) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_ENUM_VALUE,
                       "parity value class=" + std::to_string(value));
    }
    return static_cast<ctex::exec::ParityValueClass>(value);
}

ctex::exec::ParityFixtureChannel parity_fixture_channel(
    const ctex_parity_fixture_channel_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_PARITY_FIXTURE_CHANNEL_DESCRIPTOR_V1_SIZE,
                            CTEX_PARITY_FIXTURE_CHANNEL_DESCRIPTOR_CURRENT_SIZE,
                            "parity fixture channel descriptor size");
    require_executor_boolean(descriptor.filtered, "filtered");
    if (descriptor.component_count == 0 || descriptor.component_count > UINT8_MAX) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_DESCRIPTOR_VALUE,
                       "parity fixture component_count must be from 1 through 255");
    }
    return {
        .semantic = require_executor_text(descriptor.semantic, "channel semantic"),
        .value_class = parity_value_class(descriptor.value_class),
        .filtered = descriptor.filtered != 0,
        .component_count = static_cast<std::uint8_t>(descriptor.component_count),
    };
}

ctex::exec::ParityFixture parity_fixture(const ctex_parity_fixture_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_PARITY_FIXTURE_DESCRIPTOR_V1_SIZE,
                            CTEX_PARITY_FIXTURE_DESCRIPTOR_CURRENT_SIZE,
                            "parity fixture descriptor size");
    if (descriptor.channels == nullptr && descriptor.channel_count != 0) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "fixture channels=null with nonzero channel_count");
    }
    ctex::exec::ParityFixture fixture{
        .identifier = require_executor_text(descriptor.identifier, "fixture identifier"),
        .document = require_executor_text(descriptor.document, "fixture document"),
        .stroke = require_executor_text(descriptor.stroke, "fixture stroke"),
        .camera = require_executor_text(descriptor.camera, "fixture camera"),
        .material = require_executor_text(descriptor.material, "fixture material"),
        .channels = {},
    };
    fixture.channels.reserve(descriptor.channel_count);
    for (std::size_t index = 0; index < descriptor.channel_count; ++index) {
        fixture.channels.push_back(parity_fixture_channel(descriptor.channels[index]));
    }
    return fixture;
}

ctex::exec::ParityRenderedChannel parity_rendered_channel(
    const ctex_parity_rendered_channel_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_PARITY_RENDERED_CHANNEL_DESCRIPTOR_V1_SIZE,
                            CTEX_PARITY_RENDERED_CHANNEL_DESCRIPTOR_CURRENT_SIZE,
                            "rendered parity channel descriptor size");
    if (descriptor.values == nullptr && descriptor.value_count != 0) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "rendered parity values=null with nonzero value_count");
    }
    const auto values = descriptor.value_count == 0
                            ? std::span<const double>{}
                            : std::span<const double>(descriptor.values, descriptor.value_count);
    return {
        .semantic = require_executor_text(descriptor.semantic, "rendered channel semantic"),
        .values = std::vector<double>(values.begin(), values.end()),
    };
}

ctex::exec::ParityRenderedFixture parity_rendered_fixture(
    const ctex_parity_rendered_fixture_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_PARITY_RENDERED_FIXTURE_DESCRIPTOR_V1_SIZE,
                            CTEX_PARITY_RENDERED_FIXTURE_DESCRIPTOR_CURRENT_SIZE,
                            "rendered parity fixture descriptor size");
    if (descriptor.channels == nullptr && descriptor.channel_count != 0) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "rendered channels=null with nonzero channel_count");
    }
    ctex::exec::ParityRenderedFixture rendered{
        .width = descriptor.width,
        .height = descriptor.height,
        .channels = {},
    };
    rendered.channels.reserve(descriptor.channel_count);
    for (std::size_t index = 0; index < descriptor.channel_count; ++index) {
        rendered.channels.push_back(parity_rendered_channel(descriptor.channels[index]));
    }
    return rendered;
}

class CapiParityExecutor final : public ctex::exec::Executor {
public:
    explicit CapiParityExecutor(ctex::exec::ExecutorDescriptor descriptor)
        : descriptor_(std::move(descriptor)) {}

    [[nodiscard]] const ctex::exec::ExecutorDescriptor& descriptor() const noexcept override {
        return descriptor_;
    }

private:
    ctex::exec::ExecutorDescriptor descriptor_;
};

struct CapiParityRenderContext {
    std::span<const ctex_parity_fixture_descriptor> input_fixtures;
    std::span<const ctex::exec::ParityFixture> fixtures;

    [[nodiscard]] ctex::exec::ParityRenderedFixture render(
        const ctex::exec::ParityFixture& fixture,
        const ctex_parity_executor_binding_descriptor& binding) const {
        const auto found =
            std::ranges::find(fixtures, fixture.identifier, &ctex::exec::ParityFixture::identifier);
        if (found == fixtures.end()) {
            throw std::logic_error("parity callback fixture could not be resolved");
        }
        const std::size_t index = static_cast<std::size_t>(found - fixtures.begin());
        ctex_parity_rendered_fixture_descriptor rendered{
            .size = CTEX_PARITY_RENDERED_FIXTURE_DESCRIPTOR_CURRENT_SIZE,
            .width = 0,
            .height = 0,
            .channels = nullptr,
            .channel_count = 0,
        };
        ctex_result callback_result = CTEX_RESULT_INTERNAL_ERROR;
        try {
            callback_result = binding.render(&input_fixtures[index], &rendered, binding.user_data);
        } catch (...) {
            throw ctex::exec::ParityGateError("parity render callback threw an exception");
        }
        require_successful_executor_callback(callback_result, "parity render");
        return parity_rendered_fixture(rendered);
    }
};

void validate_parity_gate_arguments(const ctex_executor_registry* registry,
                                    const ctex_parity_fixture_descriptor* fixtures,
                                    std::size_t fixture_count,
                                    const ctex_parity_executor_binding_descriptor* executors,
                                    std::size_t executor_count,
                                    const ctex_parity_gate_result* const* out_result) {
    if (registry == nullptr || out_result == nullptr ||
        (fixtures == nullptr && fixture_count != 0) ||
        (executors == nullptr && executor_count != 0)) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "parity gate argument is null with a nonzero count");
    }
}

std::vector<ctex::exec::ParityFixture> parity_fixtures(
    std::span<const ctex_parity_fixture_descriptor> descriptors) {
    std::vector<ctex::exec::ParityFixture> fixtures;
    fixtures.reserve(descriptors.size());
    std::ranges::transform(descriptors, std::back_inserter(fixtures), parity_fixture);
    return fixtures;
}

std::vector<CapiParityExecutor> parity_executors(
    const ctex_executor_registry& registry,
    std::span<const ctex_parity_executor_binding_descriptor> descriptors) {
    std::vector<CapiParityExecutor> executors;
    executors.reserve(descriptors.size());
    for (const auto& descriptor : descriptors) {
        validate_structure_size(descriptor.size, CTEX_PARITY_EXECUTOR_BINDING_DESCRIPTOR_V1_SIZE,
                                CTEX_PARITY_EXECUTOR_BINDING_DESCRIPTOR_CURRENT_SIZE,
                                "parity executor binding descriptor size");
        executors.emplace_back(executor_at(registry, descriptor.executor_index));
    }
    return executors;
}

std::vector<ctex::exec::ParityExecutorBinding> parity_bindings(
    std::span<const ctex_parity_executor_binding_descriptor> descriptors,
    std::span<const CapiParityExecutor> executors, const CapiParityRenderContext& context) {
    std::vector<ctex::exec::ParityExecutorBinding> bindings;
    bindings.reserve(descriptors.size());
    for (std::size_t index = 0; index < descriptors.size(); ++index) {
        const auto* descriptor = &descriptors[index];
        ctex::exec::ParityRenderCallback render;
        if (descriptor->render != nullptr) {
            render = [&context, descriptor](const ctex::exec::ParityFixture& fixture) {
                return context.render(fixture, *descriptor);
            };
        }
        bindings.push_back({.executor = &executors[index], .render = std::move(render)});
    }
    return bindings;
}

void append_parity_json_number(std::string& output, double value) {
    if (std::isfinite(value)) {
        output += std::to_string(value);
    } else {
        append_json_text(output, std::isnan(value) ? "nan" : "infinity");
    }
}

std::string parity_gate_report_json(const ctex::exec::ParityGateReport& report) {
    std::string output = "{\"passed\":";
    output += report.passed() ? "true" : "false";
    output += ",\"executors\":[";
    for (std::size_t executor_index = 0; executor_index < report.executors.size();
         ++executor_index) {
        const auto& executor = report.executors[executor_index];
        if (executor_index != 0) {
            output.push_back(',');
        }
        output += "{\"executor\":";
        append_json_text(output, executor.executor);
        output += ",\"device\":";
        append_json_text(output, executor.device);
        output += ",\"status\":";
        append_json_text(output, ctex::exec::parity_measurement_status_name(executor.status));
        output +=
            ",\"measuredFixtures\":" + std::to_string(executor.measured_fixtures) + ",\"message\":";
        append_json_text(output, executor.message);
        output += ",\"failures\":[";
        for (std::size_t failure_index = 0; failure_index < executor.failures.size();
             ++failure_index) {
            const auto& failure = executor.failures[failure_index];
            if (failure_index != 0) {
                output.push_back(',');
            }
            output += "{\"fixture\":";
            append_json_text(output, failure.fixture);
            output += ",\"channel\":";
            append_json_text(output, failure.channel);
            output += ",\"valueIndex\":" + std::to_string(failure.value_index) +
                      ",\"measuredDeviation\":";
            append_parity_json_number(output, failure.measured_deviation);
            output += ",\"allowedDeviation\":";
            append_parity_json_number(output, failure.allowed_deviation);
            output += ",\"message\":";
            append_json_text(output, failure.message);
            output.push_back('}');
        }
        output += "]}";
    }
    output += "]}";
    return output;
}

ctex::emit::ResourceVersion host_resource_version(const char* logical_id,
                                                  std::uint64_t generation) {
    return {.logical_id = require_executor_text(logical_id, "logical_id"),
            .generation = generation};
}

ctex::exec::HostResourceHandoff host_resource(const ctex_host_resource_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_HOST_RESOURCE_DESCRIPTOR_V1_SIZE,
                            CTEX_HOST_RESOURCE_DESCRIPTOR_CURRENT_SIZE,
                            "host resource descriptor size");
    if (descriptor.owner > CTEX_HOST_RESOURCE_HOST ||
        descriptor.required_state > CTEX_HOST_RESOURCE_DEPTH_TARGET) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_ENUM_VALUE,
                       "host resource enum is invalid");
    }
    require_executor_boolean(descriptor.externally_initialized, "externally_initialized");
    require_executor_boolean(descriptor.output, "output");
    return {
        .texture = {.version = host_resource_version(descriptor.logical_id, descriptor.generation),
                    .role = require_executor_text(descriptor.role, "resource role"),
                    .format = executor_texture_format(descriptor.format),
                    .extent = {.width = descriptor.width,
                               .height = descriptor.height,
                               .layers = descriptor.layers},
                    .mip_levels = descriptor.mip_levels,
                    .tile_shape = {.width = descriptor.tile_width,
                                   .height = descriptor.tile_height},
                    .externally_initialized = descriptor.externally_initialized != 0},
        .owner = static_cast<ctex::exec::HostResourceOwner>(descriptor.owner),
        .required_state = static_cast<ctex::exec::HostResourceState>(descriptor.required_state),
        .output = descriptor.output != 0,
    };
}

ctex::exec::HostSubmissionRequest host_submission_request(
    const ctex_host_submission_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_HOST_SUBMISSION_DESCRIPTOR_V1_SIZE,
                            CTEX_HOST_SUBMISSION_DESCRIPTOR_CURRENT_SIZE,
                            "host submission descriptor size");
    if (descriptor.resources == nullptr && descriptor.resource_count != 0) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "resources=null with nonzero resource_count");
    }
    if (descriptor.replay_semantics > CTEX_HOST_REPLAY_CHECKPOINT_ONLY) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_ENUM_VALUE,
                       "host replay semantics=" + std::to_string(descriptor.replay_semantics));
    }
    ctex::exec::HostSubmissionRequest converted{
        .operation = require_executor_text(descriptor.operation, "operation"),
        .base_revision = descriptor.base_revision,
        .resources = {},
        .replay_semantics =
            static_cast<ctex::exec::HostReplaySemantics>(descriptor.replay_semantics),
    };
    converted.resources.reserve(descriptor.resource_count);
    for (std::size_t index = 0; index < descriptor.resource_count; ++index) {
        converted.resources.push_back(host_resource(descriptor.resources[index]));
    }
    return converted;
}

ctex::exec::RecoveryEvidence host_recovery(const ctex_host_recovery_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_HOST_RECOVERY_DESCRIPTOR_V1_SIZE,
                            CTEX_HOST_RECOVERY_DESCRIPTOR_CURRENT_SIZE,
                            "host recovery descriptor size");
    if (descriptor.kind > CTEX_HOST_RECOVERY_DETERMINISTIC_RECORD) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_ENUM_VALUE,
                       "host recovery kind=" + std::to_string(descriptor.kind));
    }
    require_executor_boolean(descriptor.checkpoint_complete, "checkpoint_complete");
    require_executor_boolean(descriptor.inputs_pinned, "inputs_pinned");
    return {
        .kind = static_cast<ctex::exec::RecoveryEvidenceKind>(descriptor.kind),
        .checkpoint_complete = descriptor.checkpoint_complete != 0,
        .checkpoint_revision = descriptor.checkpoint_revision,
        .operation_record_version = descriptor.operation_record_version == nullptr
                                        ? ""
                                        : descriptor.operation_record_version,
        .inputs_pinned = descriptor.inputs_pinned != 0,
        .retained_bytes = descriptor.retained_bytes,
    };
}

ctex::exec::HostCompletedResource host_completed_resource(
    const ctex_host_completed_resource_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_HOST_COMPLETED_RESOURCE_DESCRIPTOR_V1_SIZE,
                            CTEX_HOST_COMPLETED_RESOURCE_DESCRIPTOR_CURRENT_SIZE,
                            "host completed resource descriptor size");
    return {
        .version = host_resource_version(descriptor.logical_id, descriptor.generation),
        .format = executor_texture_format(descriptor.format),
        .extent = {.width = descriptor.width,
                   .height = descriptor.height,
                   .layers = descriptor.layers},
    };
}

ctex::exec::HostCompletion host_completion(const ctex_host_completion_descriptor& descriptor) {
    validate_structure_size(descriptor.size, CTEX_HOST_COMPLETION_DESCRIPTOR_V1_SIZE,
                            CTEX_HOST_COMPLETION_DESCRIPTOR_CURRENT_SIZE,
                            "host completion descriptor size");
    if (descriptor.status > CTEX_HOST_EXECUTION_CANCELLED) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_ENUM_VALUE,
                       "host execution status=" + std::to_string(descriptor.status));
    }
    if (descriptor.outputs == nullptr && descriptor.output_count != 0) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "outputs=null with nonzero output_count");
    }
    ctex::exec::HostCompletion converted{
        .token = descriptor.completion_token,
        .status = static_cast<ctex::exec::HostExecutionStatus>(descriptor.status),
        .outputs = {},
        .recovery =
            descriptor.recovery == nullptr
                ? std::nullopt
                : std::optional<ctex::exec::RecoveryEvidence>{host_recovery(*descriptor.recovery)},
        .detail = descriptor.detail == nullptr ? "" : descriptor.detail,
    };
    converted.outputs.reserve(descriptor.output_count);
    for (std::size_t index = 0; index < descriptor.output_count; ++index) {
        converted.outputs.push_back(host_completed_resource(descriptor.outputs[index]));
    }
    return converted;
}

std::size_t host_resource_identity_size(std::span<const ctex::emit::ResourceVersion> resources) {
    std::size_t required = 0;
    for (const auto& resource : resources) {
        if (resource.logical_id.size() == std::numeric_limits<std::size_t>::max() ||
            resource.logical_id.size() + 1 > std::numeric_limits<std::size_t>::max() - required) {
            throw std::overflow_error("host resource identity buffer size overflows");
        }
        required += resource.logical_id.size() + 1;
    }
    return required;
}

void copy_host_resource_versions(std::span<const ctex::emit::ResourceVersion> resources,
                                 ctex_host_resource_version* output, char* identities) {
    if (output == nullptr) {
        return;
    }
    std::size_t offset = 0;
    for (std::size_t index = 0; index < resources.size(); ++index) {
        output[index] = {.logical_id_offset = offset, .generation = resources[index].generation};
        const std::size_t size = resources[index].logical_id.size() + 1;
        std::memcpy(identities + offset, resources[index].logical_id.c_str(), size);
        offset += size;
    }
}

void query_transport_snapshot(ctex_transport_snapshot_pool& pool,
                              const ctex::image::TiledImage& image,
                              ctex_transport_revision_cursor synchronized_cursor,
                              ctex_transport_snapshot** out_snapshot,
                              ctex_transport_snapshot_query_info& out_info) {
    auto query =
        ctex::xport::query_channel_delta(pool.value, image, transport_cursor(synchronized_cursor));
    if (!query.admitted()) {
        out_info = {
            .size = CTEX_TRANSPORT_SNAPSHOT_QUERY_INFO_CURRENT_SIZE,
            .disposition = CTEX_TRANSPORT_DELTA_COMPLETE,
            .synchronized_cursor = {},
            .current_cursor = {},
            .changed_tile_count = 0,
            .indexed_tiles_visited = 0,
            .retained_bytes = 0,
            .additional_pinned_bytes = query.additional_pinned_bytes,
        };
        throw_boundary(CTEX_RESULT_OVER_BUDGET, CTEX_DIAGNOSTIC_INVALID_HOST_TRANSPORT,
                       query.detail);
    }
    auto& synchronized = *query.synchronized;
    std::vector<ctex::xport::TileMemoryLayout> layouts;
    layouts.reserve(synchronized.delta.changed_tiles.size());
    for (const auto& version : synchronized.delta.changed_tiles) {
        layouts.push_back(ctex::xport::tile_memory_layout(image, version.coordinate));
    }
    out_info = {
        .size = CTEX_TRANSPORT_SNAPSHOT_QUERY_INFO_CURRENT_SIZE,
        .disposition =
            synchronized.delta.disposition == ctex::xport::DeltaQueryDisposition::complete
                ? CTEX_TRANSPORT_DELTA_COMPLETE
                : CTEX_TRANSPORT_FULL_RESYNCHRONIZATION_REQUIRED,
        .synchronized_cursor = transport_cursor(synchronized.delta.synchronized_cursor),
        .current_cursor = transport_cursor(synchronized.delta.current_cursor),
        .changed_tile_count = synchronized.delta.changed_tiles.size(),
        .indexed_tiles_visited = synchronized.delta.indexed_tiles_visited,
        .retained_bytes = synchronized.snapshot.retained_bytes(),
        .additional_pinned_bytes = query.additional_pinned_bytes,
    };
    *out_snapshot =
        create_transport_snapshot(pool.allocator, std::move(synchronized), std::move(layouts));
}

void set_tile_history_restore_info(const ctex::doc::TileHistoryRestoreResult& result,
                                   ctex_tile_history_restore_info& info) {
    info = {
        .size = CTEX_TILE_HISTORY_RESTORE_INFO_CURRENT_SIZE,
        .tile_count = result.tile_count,
        .exchanged_storage_count = result.exchanged_storage_count,
        .copied_pixel_bytes = result.copied_pixel_bytes,
        .layer_stack_exchanged = result.layer_stack_exchanged ? 1U : 0U,
    };
}

ctex::doc::LayerCompositeRequest make_layer_composite_request(
    std::uint32_t width, std::uint32_t height,
    const ctex_layer_composite_raster_descriptor* content, std::size_t content_count,
    const ctex_layer_composite_mask_descriptor* masks, std::size_t mask_count) {
    ctex::doc::LayerCompositeRequest request{
        .width = width,
        .height = height,
        .content = {},
        .masks = {},
    };
    request.content.reserve(content_count);
    for (std::size_t index = 0; index < content_count; ++index) {
        request.content.push_back(layer_composite_raster(content[index]));
    }
    request.masks.reserve(mask_count);
    for (std::size_t index = 0; index < mask_count; ++index) {
        request.masks.push_back(layer_composite_mask(masks[index]));
    }
    return request;
}

struct LayerCompositeOutputShape {
    std::vector<std::string> semantic_ids;
    std::size_t pixel_count{};
};

LayerCompositeOutputShape layer_composite_output_shape(
    const ctex::doc::LayerCompositeResult& result) {
    LayerCompositeOutputShape shape;
    shape.semantic_ids.reserve(result.channels.size());
    for (const ctex::doc::LayerCompositeChannel& channel : result.channels) {
        shape.semantic_ids.push_back(channel.semantic_id);
        if (channel.pixels.size() > std::numeric_limits<std::size_t>::max() - shape.pixel_count) {
            throw std::overflow_error("layer composite output pixel count overflow");
        }
        shape.pixel_count += channel.pixels.size();
    }
    return shape;
}

struct LayerCompositeOutputBuffers {
    ctex_layer_composite_channel_info* channels{};
    char* semantic_ids{};
    ctex_vec4f* pixels{};
};

void write_layer_composite_channel(const ctex::doc::LayerCompositeChannel& channel,
                                   std::size_t index, std::size_t semantic_offset,
                                   std::size_t pixel_offset,
                                   const LayerCompositeOutputBuffers& output) {
    const std::size_t name_size = channel.semantic_id.size() + 1;
    if (output.channels != nullptr) {
        output.channels[index] = {
            .component_count = channel.component_count,
            .semantic_id_offset = semantic_offset,
            .semantic_id_size = name_size,
            .pixel_offset = pixel_offset,
            .pixel_count = channel.pixels.size(),
        };
    }
    if (output.semantic_ids != nullptr) {
        std::memcpy(output.semantic_ids + semantic_offset, channel.semantic_id.c_str(), name_size);
    }
    if (output.pixels == nullptr) {
        return;
    }
    for (std::size_t pixel = 0; pixel < channel.pixels.size(); ++pixel) {
        const ctex::graph::ColourValue value = channel.pixels[pixel];
        output.pixels[pixel_offset + pixel] = {value.r, value.g, value.b, value.a};
    }
}

void write_layer_composite_output(const ctex::doc::LayerCompositeResult& result,
                                  const LayerCompositeOutputBuffers& output) {
    std::size_t semantic_offset = 0;
    std::size_t pixel_offset = 0;
    for (std::size_t index = 0; index < result.channels.size(); ++index) {
        const ctex::doc::LayerCompositeChannel& channel = result.channels[index];
        write_layer_composite_channel(channel, index, semantic_offset, pixel_offset, output);
        semantic_offset += channel.semantic_id.size() + 1;
        pixel_offset += channel.pixels.size();
    }
}

void publish_layer_composite(const ctex::doc::LayerCompositeResult& result,
                             ctex_layer_composite_info& info,
                             const LayerCompositeOutputBuffers& output,
                             std::size_t channel_capacity, std::size_t semantic_id_size,
                             std::size_t pixel_capacity) {
    const LayerCompositeOutputShape shape = layer_composite_output_shape(result);
    const std::size_t required_semantic_size = texture_set_id_buffer_size(shape.semantic_ids);
    validate_output_array(output.channels, channel_capacity, result.channels.size(), "channels");
    validate_string_buffer(output.semantic_ids, semantic_id_size, required_semantic_size);
    validate_output_array(output.pixels, pixel_capacity, shape.pixel_count, "pixels");
    info = {
        .size = CTEX_LAYER_COMPOSITE_INFO_CURRENT_SIZE,
        .width = result.width,
        .height = result.height,
        .channel_count = result.channels.size(),
        .required_semantic_id_size = required_semantic_size,
        .required_pixel_count = shape.pixel_count,
    };
    write_layer_composite_output(result, output);
}

struct LayerSnapshotShape {
    std::size_t string_size{};
    std::size_t pixel_count{};
    std::size_t coverage_count{};
    std::size_t mask_value_count{};
};

void add_layer_snapshot_size(std::size_t value, std::size_t& total, std::string_view name) {
    if (value > std::numeric_limits<std::size_t>::max() - total) {
        throw std::overflow_error(std::string("layer snapshot ") + std::string(name) +
                                  " count overflow");
    }
    total += value;
}

LayerSnapshotShape layer_snapshot_shape(const ctex::doc::LayerCompositeRequest& snapshot) {
    LayerSnapshotShape shape;
    for (const ctex::doc::LayerCompositeRaster& raster : snapshot.content) {
        add_layer_snapshot_size(raster.entry_identifier.size() + 1, shape.string_size, "string");
        add_layer_snapshot_size(raster.semantic_id.size() + 1, shape.string_size, "string");
        add_layer_snapshot_size(raster.pixels.size(), shape.pixel_count, "pixel");
        add_layer_snapshot_size(raster.coverage.size(), shape.coverage_count, "coverage");
    }
    for (const ctex::doc::LayerCompositeMaskRaster& mask : snapshot.masks) {
        add_layer_snapshot_size(mask.mask_identifier.size() + 1, shape.string_size, "string");
        add_layer_snapshot_size(mask.values.size(), shape.mask_value_count, "mask value");
    }
    return shape;
}

struct LayerSnapshotOutputBuffers {
    ctex_layer_snapshot_content_info* content{};
    ctex_layer_snapshot_mask_info* masks{};
    char* strings{};
    ctex_vec4f* pixels{};
    float* coverage{};
    double* mask_values{};
};

void write_layer_snapshot_content(const ctex::doc::LayerCompositeRaster& raster, std::size_t index,
                                  std::size_t& string_offset, std::size_t& pixel_offset,
                                  std::size_t& coverage_offset,
                                  const LayerSnapshotOutputBuffers& output) {
    const std::size_t entry_size = raster.entry_identifier.size() + 1;
    const std::size_t semantic_offset = string_offset + entry_size;
    const std::size_t semantic_size = raster.semantic_id.size() + 1;
    if (output.content != nullptr) {
        output.content[index] = {
            .width = raster.width,
            .height = raster.height,
            .entry_identifier_offset = string_offset,
            .entry_identifier_size = entry_size,
            .semantic_id_offset = semantic_offset,
            .semantic_id_size = semantic_size,
            .pixel_offset = pixel_offset,
            .pixel_count = raster.pixels.size(),
            .coverage_offset = coverage_offset,
            .coverage_count = raster.coverage.size(),
        };
    }
    if (output.strings != nullptr) {
        std::memcpy(output.strings + string_offset, raster.entry_identifier.c_str(), entry_size);
        std::memcpy(output.strings + semantic_offset, raster.semantic_id.c_str(), semantic_size);
    }
    if (output.pixels != nullptr) {
        for (std::size_t pixel = 0; pixel < raster.pixels.size(); ++pixel) {
            const ctex::graph::ColourValue value = raster.pixels[pixel];
            output.pixels[pixel_offset + pixel] = {value.r, value.g, value.b, value.a};
        }
    }
    if (output.coverage != nullptr) {
        std::copy(raster.coverage.begin(), raster.coverage.end(),
                  output.coverage + coverage_offset);
    }
    string_offset = semantic_offset + semantic_size;
    pixel_offset += raster.pixels.size();
    coverage_offset += raster.coverage.size();
}

void write_layer_snapshot_mask(const ctex::doc::LayerCompositeMaskRaster& mask, std::size_t index,
                               std::size_t& string_offset, std::size_t& value_offset,
                               const LayerSnapshotOutputBuffers& output) {
    const std::size_t identifier_size = mask.mask_identifier.size() + 1;
    if (output.masks != nullptr) {
        output.masks[index] = {
            .width = mask.width,
            .height = mask.height,
            .mask_identifier_offset = string_offset,
            .mask_identifier_size = identifier_size,
            .value_offset = value_offset,
            .value_count = mask.values.size(),
        };
    }
    if (output.strings != nullptr) {
        std::memcpy(output.strings + string_offset, mask.mask_identifier.c_str(), identifier_size);
    }
    if (output.mask_values != nullptr) {
        std::copy(mask.values.begin(), mask.values.end(), output.mask_values + value_offset);
    }
    string_offset += identifier_size;
    value_offset += mask.values.size();
}

void write_layer_snapshot(const ctex::doc::LayerCompositeRequest& snapshot,
                          const LayerSnapshotOutputBuffers& output) {
    std::size_t string_offset = 0;
    std::size_t pixel_offset = 0;
    std::size_t coverage_offset = 0;
    for (std::size_t index = 0; index < snapshot.content.size(); ++index) {
        write_layer_snapshot_content(snapshot.content[index], index, string_offset, pixel_offset,
                                     coverage_offset, output);
    }
    std::size_t mask_value_offset = 0;
    for (std::size_t index = 0; index < snapshot.masks.size(); ++index) {
        write_layer_snapshot_mask(snapshot.masks[index], index, string_offset, mask_value_offset,
                                  output);
    }
}

void publish_layer_snapshot(const ctex::doc::LayerCompositeRequest& snapshot,
                            ctex_layer_snapshot_info& info,
                            const LayerSnapshotOutputBuffers& output, std::size_t content_capacity,
                            std::size_t mask_capacity, std::size_t string_size,
                            std::size_t pixel_capacity, std::size_t coverage_capacity,
                            std::size_t mask_value_capacity) {
    const LayerSnapshotShape shape = layer_snapshot_shape(snapshot);
    validate_output_array(output.content, content_capacity, snapshot.content.size(), "content");
    validate_output_array(output.masks, mask_capacity, snapshot.masks.size(), "masks");
    validate_string_buffer(output.strings, string_size, shape.string_size);
    validate_output_array(output.pixels, pixel_capacity, shape.pixel_count, "pixels");
    validate_output_array(output.coverage, coverage_capacity, shape.coverage_count, "coverage");
    validate_output_array(output.mask_values, mask_value_capacity, shape.mask_value_count,
                          "mask_values");
    info = {
        .size = CTEX_LAYER_SNAPSHOT_INFO_CURRENT_SIZE,
        .width = snapshot.width,
        .height = snapshot.height,
        .content_count = snapshot.content.size(),
        .mask_count = snapshot.masks.size(),
        .required_string_size = shape.string_size,
        .required_pixel_count = shape.pixel_count,
        .required_coverage_count = shape.coverage_count,
        .required_mask_value_count = shape.mask_value_count,
    };
    write_layer_snapshot(snapshot, output);
}

ctex::doc::TextureSetTransaction& require_transaction(ctex_texture_set_transaction& transaction) {
    if (!transaction.value.has_value()) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_TILE_HISTORY,
                       "texture-set transaction was already consumed");
    }
    return *transaction.value;
}

struct PreviewQualityOptions {
    std::vector<std::vector<ctex::xport::ResourceRequirement>> requirement_storage;
    std::vector<ctex::xport::PreviewQualityOption> values;
};

PreviewQualityOptions preview_quality_options(
    const ctex_preview_quality_admission_descriptor& descriptor) {
    if (descriptor.option_count != 0 && descriptor.options == nullptr) {
        throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                       "preview quality options are null with a non-zero count");
    }
    PreviewQualityOptions result;
    result.requirement_storage.reserve(descriptor.option_count);
    result.values.reserve(descriptor.option_count);
    for (std::size_t option_index = 0; option_index < descriptor.option_count; ++option_index) {
        const ctex_preview_quality_option& source = descriptor.options[option_index];
        validate_structure_size(source.size, CTEX_PREVIEW_QUALITY_OPTION_V1_SIZE,
                                CTEX_PREVIEW_QUALITY_OPTION_CURRENT_SIZE,
                                "preview quality option size");
        if (source.requirement_count != 0 && source.requirements == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           "preview requirements are null with a non-zero count");
        }
        result.requirement_storage.emplace_back();
        auto& requirements = result.requirement_storage.back();
        requirements.reserve(source.requirement_count);
        for (std::size_t index = 0; index < source.requirement_count; ++index) {
            const ctex_resource_requirement& requirement = source.requirements[index];
            validate_structure_size(requirement.size, CTEX_RESOURCE_REQUIREMENT_V1_SIZE,
                                    CTEX_RESOURCE_REQUIREMENT_CURRENT_SIZE,
                                    "preview resource requirement size");
            requirements.push_back(
                {.category = static_cast<ctex::xport::ResourceCategory>(requirement.category),
                 .physical_bytes = requirement.physical_bytes,
                 .roles = requirement.roles});
        }
        result.values.push_back({.width = source.width,
                                 .height = source.height,
                                 .requirements = requirements,
                                 .derived_work_deferred = source.derived_work_deferred != 0});
    }
    return result;
}

