extern "C" ctex_result ctex_paint_rasterize_decal(const ctex_paint_decal_descriptor* descriptor,
                                                  ctex_paint_decal_info* out_info,
                                                  const ctex_paint_decal_outputs* outputs) {
    return call_boundary("ctex_paint_rasterize_decal", [&] {
        if (descriptor == nullptr || out_info == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           descriptor == nullptr ? "descriptor=null" : "out_info=null");
        }
        validate_structure_size(descriptor->size, CTEX_PAINT_DECAL_DESCRIPTOR_V1_SIZE,
                                CTEX_PAINT_DECAL_DESCRIPTOR_CURRENT_SIZE, "descriptor.size");
        validate_structure_size(out_info->size, CTEX_PAINT_DECAL_INFO_V1_SIZE,
                                CTEX_PAINT_DECAL_INFO_CURRENT_SIZE, "out_info.size");
        const std::size_t pixel_count = bounded_paint_pixel_count(
            descriptor->width, descriptor->height, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL);
        const std::size_t material_pixel_count =
            bounded_paint_pixel_count(descriptor->material_width, descriptor->material_height,
                                      CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL);
        try {
            const ctex::paint::CachedSurfaceMaps surface =
                paint_decal_surface(*descriptor, pixel_count);
            const auto layer = paint_tool_channels(descriptor->enabled_layer_snapshot,
                                                   descriptor->enabled_layer_channel_count,
                                                   pixel_count, "enabled_layer_snapshot");
            ctex::paint::DecalMaterial material{
                .width = descriptor->material_width,
                .height = descriptor->material_height,
                .channels =
                    paint_tool_channels(descriptor->material, descriptor->material_channel_count,
                                        material_pixel_count, "material"),
                .opacity = {},
            };
            require_paint_tool_array(descriptor->material_opacity,
                                     descriptor->material_opacity_count, "material_opacity");
            if (descriptor->material_opacity_count != material_pixel_count) {
                throw std::invalid_argument(
                    "decal material opacity count does not match its dimensions");
            }
            material.opacity.assign(descriptor->material_opacity,
                                    descriptor->material_opacity + material_pixel_count);
            const PaintMaskStorage masks = paint_mask_storage(descriptor->masks);
            if (descriptor->blend_mode == nullptr) {
                throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                               "blend_mode=null");
            }
            const ctex::paint::DecalRasterSettings settings{
                .blend_mode = descriptor->blend_mode,
                .masks = masks.inputs(),
                .rejection_acceptance = paint_fill_optional_view(
                    descriptor->rejection_acceptance, descriptor->rejection_acceptance_count,
                    "rejection_acceptance"),
            };
            const ctex::paint::DecalRasterResult result = ctex::paint::rasterize_decal(
                surface, layer, paint_decal_placement(descriptor->placement), material, settings);
            const ctex::paint::DecalTransform& resolved = result.frame.resolved_transform;
            *out_info = {
                .size = CTEX_PAINT_DECAL_INFO_CURRENT_SIZE,
                .resolved_placement = {.position = {result.frame.origin.x, result.frame.origin.y,
                                                    result.frame.origin.z},
                                       .surface_normal = {result.frame.normal.x,
                                                          result.frame.normal.y,
                                                          result.frame.normal.z},
                                       .transform = {.rotation_radians = resolved.rotation_radians,
                                                     .uniform_scale = resolved.uniform_scale,
                                                     .axis_scale = {resolved.axis_scale.x,
                                                                    resolved.axis_scale.y}}},
                .frame_tangent = {result.frame.tangent.x, result.frame.tangent.y,
                                  result.frame.tangent.z},
                .frame_bitangent = {result.frame.bitangent.x, result.frame.bitangent.y,
                                    result.frame.bitangent.z},
                .frame_scale = {result.frame.scale.x, result.frame.scale.y},
                .rotation_clamped =
                    result.parameter_report.clamp_for(ctex::paint::decal_rotation_parameter.name)
                        .has_value(),
                .uniform_scale_clamped =
                    result.parameter_report
                        .clamp_for(ctex::paint::decal_uniform_scale_parameter.name)
                        .has_value(),
                .axis_scale_x_clamped =
                    result.parameter_report
                        .clamp_for(ctex::paint::decal_axis_scale_x_parameter.name)
                        .has_value(),
                .axis_scale_y_clamped =
                    result.parameter_report
                        .clamp_for(ctex::paint::decal_axis_scale_y_parameter.name)
                        .has_value(),
                .applied_channel_count = result.channels.size(),
                .required_pixels_per_channel = pixel_count,
            };
            validate_paint_decal_outputs(outputs, result, pixel_count);
            copy_paint_decal_outputs(outputs, result);
        } catch (const std::invalid_argument& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL,
                           error.what());
        }
    });
}

extern "C" ctex_result ctex_paint_apply_projection(
    const ctex_paint_projection_descriptor* descriptor, ctex_paint_projection_info* out_info,
    const ctex_paint_projection_outputs* outputs) {
    return call_boundary("ctex_paint_apply_projection", [&] {
        if (descriptor == nullptr || out_info == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           descriptor == nullptr ? "descriptor=null" : "out_info=null");
        }
        validate_structure_size(descriptor->size, CTEX_PAINT_PROJECTION_DESCRIPTOR_V1_SIZE,
                                CTEX_PAINT_PROJECTION_DESCRIPTOR_CURRENT_SIZE, "descriptor.size");
        validate_structure_size(out_info->size, CTEX_PAINT_PROJECTION_INFO_V1_SIZE,
                                CTEX_PAINT_PROJECTION_INFO_CURRENT_SIZE, "out_info.size");
        const std::size_t pixel_count = bounded_paint_pixel_count(
            descriptor->width, descriptor->height, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL);
        const std::size_t material_pixel_count =
            bounded_paint_pixel_count(descriptor->material_width, descriptor->material_height,
                                      CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL);
        try {
            const ctex::paint::CachedSurfaceMaps surface =
                paint_projection_surface(*descriptor, pixel_count);
            const auto layer = paint_tool_channels(descriptor->enabled_layer_snapshot,
                                                   descriptor->enabled_layer_channel_count,
                                                   pixel_count, "enabled_layer_snapshot");
            ctex::paint::DecalMaterial material{
                .width = descriptor->material_width,
                .height = descriptor->material_height,
                .channels =
                    paint_tool_channels(descriptor->material, descriptor->material_channel_count,
                                        material_pixel_count, "material"),
                .opacity = {},
            };
            require_paint_tool_array(descriptor->material_opacity,
                                     descriptor->material_opacity_count, "material_opacity");
            if (descriptor->material_opacity_count != material_pixel_count) {
                throw std::invalid_argument(
                    "projection material opacity count does not match its dimensions");
            }
            material.opacity.assign(descriptor->material_opacity,
                                    descriptor->material_opacity + material_pixel_count);
            if (descriptor->blend_mode == nullptr) {
                throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                               "blend_mode=null");
            }
            const PaintMaskStorage masks = paint_mask_storage(descriptor->masks);
            const ctex::paint::ProjectionSettings settings{
                .mapping = paint_projection_mapping(*descriptor, pixel_count),
                .blend_mode = descriptor->blend_mode,
                .masks = masks.inputs(),
                .rejection_acceptance = paint_fill_optional_view(
                    descriptor->rejection_acceptance, descriptor->rejection_acceptance_count,
                    "rejection_acceptance"),
            };
            const ctex::paint::ProjectionResult result =
                ctex::paint::apply_projection(surface, layer, material, settings);
            const auto& report = result.parameter_report;
            *out_info = {
                .size = CTEX_PAINT_PROJECTION_INFO_CURRENT_SIZE,
                .resolved_mode = descriptor->mode,
                .resolved_planar_extent =
                    {resolved_paint_parameter(
                         report, ctex::paint::projection_planar_extent_x_parameter.name,
                         descriptor->planar_extent.x),
                     resolved_paint_parameter(
                         report, ctex::paint::projection_planar_extent_y_parameter.name,
                         descriptor->planar_extent.y)},
                .resolved_triplanar_scale = resolved_paint_parameter(
                    report, ctex::paint::projection_triplanar_scale_parameter.name,
                    descriptor->triplanar_scale),
                .resolved_triplanar_offset =
                    {resolved_paint_parameter(
                         report, ctex::paint::projection_triplanar_offset_x_parameter.name,
                         descriptor->triplanar_offset.x),
                     resolved_paint_parameter(
                         report, ctex::paint::projection_triplanar_offset_y_parameter.name,
                         descriptor->triplanar_offset.y)},
                .planar_extent_x_clamped =
                    report.clamp_for(ctex::paint::projection_planar_extent_x_parameter.name)
                        .has_value(),
                .planar_extent_y_clamped =
                    report.clamp_for(ctex::paint::projection_planar_extent_y_parameter.name)
                        .has_value(),
                .triplanar_scale_clamped =
                    report.clamp_for(ctex::paint::projection_triplanar_scale_parameter.name)
                        .has_value(),
                .triplanar_offset_x_clamped =
                    report.clamp_for(ctex::paint::projection_triplanar_offset_x_parameter.name)
                        .has_value(),
                .triplanar_offset_y_clamped =
                    report.clamp_for(ctex::paint::projection_triplanar_offset_y_parameter.name)
                        .has_value(),
                .applied_channel_count = result.channels.size(),
                .required_sample_count = pixel_count,
                .required_pixels_per_channel = pixel_count,
            };
            validate_paint_projection_outputs(outputs, result, pixel_count);
            copy_paint_projection_outputs(outputs, result);
        } catch (const std::invalid_argument& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL,
                           error.what());
        }
    });
}

extern "C" ctex_result ctex_paint_apply_text(const ctex_paint_text_descriptor* descriptor,
                                             ctex_paint_text_info* out_info,
                                             const ctex_paint_text_outputs* outputs) {
    return call_boundary("ctex_paint_apply_text", [&] {
        const std::size_t pixel_count = validate_paint_text_call(descriptor, out_info);
        try {
            const ctex::paint::CachedSurfaceMaps surface =
                paint_text_surface(*descriptor, pixel_count);
            const auto layer = paint_tool_channels(descriptor->enabled_layer_snapshot,
                                                   descriptor->enabled_layer_channel_count,
                                                   pixel_count, "enabled_layer_snapshot");
            const auto material =
                paint_text_material(descriptor->material, descriptor->material_channel_count);
            const ctex::paint::SuppliedFont font = paint_text_font(descriptor->font);
            const PaintMaskStorage masks = paint_mask_storage(descriptor->masks);
            const ctex::paint::TextDecalSettings settings{
                .layout = {.tracking_em = descriptor->tracking_em,
                           .alignment = paint_text_alignment(descriptor->alignment)},
                .size = descriptor->text_size,
                .placement = paint_decal_placement(descriptor->placement),
                .decal = {.blend_mode = descriptor->blend_mode,
                          .masks = masks.inputs(),
                          .rejection_acceptance = paint_fill_optional_view(
                              descriptor->rejection_acceptance,
                              descriptor->rejection_acceptance_count, "rejection_acceptance")},
            };
            const ctex::paint::TextDecalResult result = ctex::paint::apply_text_decal(
                surface, layer, material, font,
                std::string_view(descriptor->utf8, descriptor->utf8_size), settings);
            const ctex::paint::DecalTransform& resolved = result.decal.frame.resolved_transform;
            *out_info = {
                .size = CTEX_PAINT_TEXT_INFO_CURRENT_SIZE,
                .resolved_tracking_em = result.text.tracking_em,
                .resolved_alignment = descriptor->alignment,
                .resolved_text_size = result.size,
                .tracking_clamped =
                    result.parameter_report.clamp_for(ctex::paint::text_tracking_parameter.name)
                        .has_value(),
                .text_size_clamped =
                    result.parameter_report.clamp_for(ctex::paint::text_size_parameter.name)
                        .has_value(),
                .raster_width = result.text.width,
                .raster_height = result.text.height,
                .line_count = result.text.line_count,
                .width_em = result.text.width_em,
                .height_em = result.text.height_em,
                .resolved_placement =
                    {.position = {result.decal.frame.origin.x, result.decal.frame.origin.y,
                                  result.decal.frame.origin.z},
                     .surface_normal = {result.decal.frame.normal.x, result.decal.frame.normal.y,
                                        result.decal.frame.normal.z},
                     .transform = {.rotation_radians = resolved.rotation_radians,
                                   .uniform_scale = resolved.uniform_scale,
                                   .axis_scale = {resolved.axis_scale.x, resolved.axis_scale.y}}},
                .frame_tangent = {result.decal.frame.tangent.x, result.decal.frame.tangent.y,
                                  result.decal.frame.tangent.z},
                .frame_bitangent = {result.decal.frame.bitangent.x, result.decal.frame.bitangent.y,
                                    result.decal.frame.bitangent.z},
                .frame_scale = {result.decal.frame.scale.x, result.decal.frame.scale.y},
                .rotation_clamped =
                    result.parameter_report.clamp_for(ctex::paint::decal_rotation_parameter.name)
                        .has_value(),
                .uniform_scale_clamped =
                    result.parameter_report
                        .clamp_for(ctex::paint::decal_uniform_scale_parameter.name)
                        .has_value(),
                .axis_scale_x_clamped =
                    result.parameter_report
                        .clamp_for(ctex::paint::decal_axis_scale_x_parameter.name)
                        .has_value(),
                .axis_scale_y_clamped =
                    result.parameter_report
                        .clamp_for(ctex::paint::decal_axis_scale_y_parameter.name)
                        .has_value(),
                .editable_revision = result.decal.editable_revision,
                .applied_channel_count = result.decal.channels.size(),
                .required_codepoint_count = result.text.codepoints.size(),
                .required_raster_opacity_count = result.text.opacity.size(),
                .required_pixels_per_channel = pixel_count,
            };
            validate_paint_text_outputs(outputs, result, pixel_count);
            copy_paint_text_outputs(outputs, result);
        } catch (const std::invalid_argument& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL,
                           error.what());
        }
    });
}

extern "C" ctex_result ctex_paint_apply_particles(ctex_pick_index* index,
                                                  const ctex_paint_particle_descriptor* descriptor,
                                                  ctex_paint_particle_info* out_info,
                                                  const ctex_paint_particle_outputs* outputs) {
    return call_boundary("ctex_paint_apply_particles", [&] {
        const std::size_t pixel_count = validate_paint_particle_call(index, descriptor, out_info);
        try {
            const auto texture_sets =
                pick_bindings(descriptor->texture_sets, descriptor->texture_set_count);
            const ctex::paint::CachedSurfaceMaps surface =
                paint_particle_surface(*descriptor, pixel_count);
            const auto layer = paint_tool_channels(descriptor->enabled_layer_snapshot,
                                                   descriptor->enabled_layer_channel_count,
                                                   pixel_count, "enabled_layer_snapshot");
            const auto material = paint_tool_channels(
                descriptor->material, descriptor->material_channel_count, pixel_count, "material");
            const PaintMaskStorage masks = paint_mask_storage(descriptor->masks);
            const ctex::paint::ParticleResult result = ctex::paint::apply_particles(
                index->value, index->mesh->state->mesh_binding(), texture_sets, surface, layer,
                material,
                {.position = stroke_vec(descriptor->emitter_position),
                 .direction = stroke_vec(descriptor->emitter_direction)},
                paint_particle_settings(descriptor->simulation),
                {.blend_mode = descriptor->blend_mode,
                 .masks = masks.inputs(),
                 .rejection_acceptance = paint_fill_optional_view(
                     descriptor->rejection_acceptance, descriptor->rejection_acceptance_count,
                     "rejection_acceptance")});
            const std::size_t texture_set_id_size =
                paint_particle_texture_set_id_size(result.simulation.contacts);
            set_paint_particle_info(*out_info, result, texture_set_id_size, pixel_count);
            validate_paint_particle_outputs(outputs, result, pixel_count, texture_set_id_size);
            copy_paint_particle_outputs(outputs, result, texture_set_id_size);
        } catch (const std::invalid_argument& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL,
                           error.what());
        }
    });
}

extern "C" ctex_result ctex_paint_pick_enabled_channels(
    const ctex_paint_picker_descriptor* descriptor, ctex_paint_picker_info* out_info,
    ctex_paint_picker_channel_value* channels, std::size_t channel_capacity, char* strings,
    std::size_t string_capacity) {
    return call_boundary("ctex_paint_pick_enabled_channels", [&] {
        if (descriptor == nullptr || out_info == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           descriptor == nullptr ? "descriptor=null" : "out_info=null");
        }
        validate_structure_size(descriptor->size, CTEX_PAINT_PICKER_DESCRIPTOR_V1_SIZE,
                                CTEX_PAINT_PICKER_DESCRIPTOR_CURRENT_SIZE, "descriptor.size");
        validate_structure_size(out_info->size, CTEX_PAINT_PICKER_INFO_V1_SIZE,
                                CTEX_PAINT_PICKER_INFO_CURRENT_SIZE, "out_info.size");
        try {
            const PaintPickerViews texture_views =
                paint_picker_views(descriptor->texture_views, descriptor->texture_view_count);
            const ctex::paint::PickerResult result = ctex::paint::pick_enabled_channels(
                paint_picker_hit(*descriptor), texture_views.views);
            const std::vector<std::string> packed_strings = paint_picker_strings(result);
            const std::size_t required_string_size = texture_set_id_buffer_size(packed_strings);
            set_paint_picker_info(*out_info, result, packed_strings, required_string_size);
            validate_output_array(channels, channel_capacity, result.channels.size(), "channels");
            validate_string_buffer(strings, string_capacity, required_string_size);
            copy_paint_picker_outputs(result, packed_strings, channels, strings);
        } catch (const std::invalid_argument& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL,
                           error.what());
        }
    });
}

extern "C" ctex_result ctex_paint_select_colour_id(
    const ctex_paint_colour_id_descriptor* descriptor, ctex_paint_colour_id_info* out_info,
    double* values, std::size_t value_capacity) {
    return call_boundary("ctex_paint_select_colour_id", [&] {
        if (descriptor == nullptr || out_info == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           descriptor == nullptr ? "descriptor=null" : "out_info=null");
        }
        validate_structure_size(descriptor->size, CTEX_PAINT_COLOUR_ID_DESCRIPTOR_V1_SIZE,
                                CTEX_PAINT_COLOUR_ID_DESCRIPTOR_CURRENT_SIZE, "descriptor.size");
        validate_structure_size(out_info->size, CTEX_PAINT_COLOUR_ID_INFO_V1_SIZE,
                                CTEX_PAINT_COLOUR_ID_INFO_CURRENT_SIZE, "out_info.size");
        try {
            const std::size_t pixel_count = bounded_paint_pixel_count(
                descriptor->width, descriptor->height, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL);
            const std::vector pixels = paint_colour_id_pixels(*descriptor, pixel_count);
            const ctex::paint::ColourIdSelection selection = ctex::paint::select_colour_id(
                {.width = descriptor->width, .height = descriptor->height, .pixels = pixels},
                paint_colour(descriptor->picked_colour), descriptor->tolerance);
            set_paint_colour_id_info(*out_info, selection);
            validate_output_array(values, value_capacity, selection.values.size(), "values");
            if (values != nullptr) {
                std::copy(selection.values.begin(), selection.values.end(), values);
            }
        } catch (const std::invalid_argument& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL,
                           error.what());
        }
    });
}

extern "C" ctex_result ctex_paint_get_parameter_catalogue(
    ctex_paint_parameter_descriptor* parameters, std::size_t parameter_capacity, char* names,
    std::size_t name_capacity, ctex_paint_parameter_catalogue_info* out_info) {
    return call_boundary("ctex_paint_get_parameter_catalogue", [&] {
        if (out_info == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           "out_info=null");
        }
        validate_structure_size(out_info->size, CTEX_PAINT_PARAMETER_CATALOGUE_INFO_V1_SIZE,
                                CTEX_PAINT_PARAMETER_CATALOGUE_INFO_CURRENT_SIZE, "out_info.size");
        const std::span catalogue = paint_parameter_catalogue();
        const std::size_t required_name_size = paint_parameter_name_size(catalogue);
        *out_info = {.size = CTEX_PAINT_PARAMETER_CATALOGUE_INFO_CURRENT_SIZE,
                     .required_parameter_count = catalogue.size(),
                     .required_name_size = required_name_size};
        validate_output_array(parameters, parameter_capacity, catalogue.size(), "parameters");
        validate_string_buffer(names, name_capacity, required_name_size);
        copy_paint_parameter_catalogue(catalogue, parameters, names);
    });
}

extern "C" ctex_result ctex_paint_validate_parameter(
    const char* name, std::uint32_t context, double supplied,
    ctex_paint_parameter_validation_info* out_info) {
    return call_boundary("ctex_paint_validate_parameter", [&] {
        if (name == nullptr || out_info == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           name == nullptr ? "name=null" : "out_info=null");
        }
        validate_structure_size(out_info->size, CTEX_PAINT_PARAMETER_VALIDATION_INFO_V1_SIZE,
                                CTEX_PAINT_PARAMETER_VALIDATION_INFO_CURRENT_SIZE, "out_info.size");
        try {
            const PaintParameterCatalogueEntry& entry = paint_parameter_entry(name, context);
            if (entry.integral && std::isfinite(supplied) && std::trunc(supplied) != supplied) {
                throw std::invalid_argument("integer paint parameter requires an integral value");
            }
            ctex::paint::ToolParameterReport report;
            const double resolved =
                ctex::paint::validate_tool_parameter(entry.descriptor, supplied, report);
            *out_info = {.size = CTEX_PAINT_PARAMETER_VALIDATION_INFO_CURRENT_SIZE,
                         .supplied = supplied,
                         .resolved = resolved,
                         .clamped = !report.clamps.empty()};
        } catch (const std::invalid_argument& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL,
                           error.what());
        }
    });
}

extern "C" ctex_result ctex_paint_select_screen(
    ctex_pick_index* index, const ctex_paint_screen_selection_descriptor* descriptor,
    ctex_paint_selection_info* out_info, const ctex_paint_selection_outputs* outputs) {
    return call_boundary("ctex_paint_select_screen", [&] {
        if (index == nullptr || descriptor == nullptr || out_info == nullptr ||
            descriptor->surface == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           "index, descriptor, surface and out_info are required");
        }
        validate_structure_size(descriptor->size, CTEX_PAINT_SCREEN_SELECTION_DESCRIPTOR_V1_SIZE,
                                CTEX_PAINT_SCREEN_SELECTION_DESCRIPTOR_CURRENT_SIZE,
                                "descriptor.size");
        validate_structure_size(out_info->size, CTEX_PAINT_SELECTION_INFO_V1_SIZE,
                                CTEX_PAINT_SELECTION_INFO_CURRENT_SIZE, "out_info.size");
        try {
            const ctex::paint::CachedSurfaceMaps surface =
                paint_selection_surface(*descriptor->surface);
            const ctex::pick::ScreenRegionView view = pick_screen_view(descriptor->view);
            ctex::paint::SelectionResult selection;
            if (descriptor->kind == CTEX_PAINT_SELECTION_SCREEN_RECTANGLE) {
                selection = ctex::paint::select_screen_rectangle(
                    index->value, index->mesh->state->mesh_binding(), surface,
                    {{descriptor->minimum.x, descriptor->minimum.y},
                     {descriptor->maximum.x, descriptor->maximum.y}},
                    view);
            } else if (descriptor->kind == CTEX_PAINT_SELECTION_SCREEN_LASSO) {
                const std::vector points = paint_selection_lasso(*descriptor);
                selection = ctex::paint::select_screen_lasso(
                    index->value, index->mesh->state->mesh_binding(), surface, points, view);
            } else {
                throw std::invalid_argument("screen selection kind is invalid");
            }
            publish_paint_selection(selection, std::nullopt, *out_info, outputs);
        } catch (const std::invalid_argument& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL,
                           error.what());
        }
    });
}

extern "C" ctex_result ctex_paint_select_polygon(
    const ctex_paint_polygon_selection_descriptor* descriptor, ctex_paint_selection_info* out_info,
    const ctex_paint_selection_outputs* outputs) {
    return call_boundary("ctex_paint_select_polygon", [&] {
        if (descriptor == nullptr || out_info == nullptr || descriptor->surface == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           "descriptor, surface and out_info are required");
        }
        validate_structure_size(descriptor->size, CTEX_PAINT_POLYGON_SELECTION_DESCRIPTOR_V1_SIZE,
                                CTEX_PAINT_POLYGON_SELECTION_DESCRIPTOR_CURRENT_SIZE,
                                "descriptor.size");
        validate_structure_size(out_info->size, CTEX_PAINT_SELECTION_INFO_V1_SIZE,
                                CTEX_PAINT_SELECTION_INFO_CURRENT_SIZE, "out_info.size");
        try {
            const ctex::paint::CachedSurfaceMaps surface =
                paint_selection_surface(*descriptor->surface);
            const ctex::paint::PolygonSelectionMode mode =
                paint_polygon_selection_mode(descriptor->kind);
            const std::vector topology = paint_fill_topology(descriptor->triangle_topology,
                                                             descriptor->triangle_topology_count);
            const ctex::paint::SelectionResult selection = ctex::paint::select_polygon(
                surface, {.mode = mode,
                          .picked_texel = descriptor->picked_texel,
                          .maximum_angle_degrees = descriptor->maximum_angle_degrees,
                          .triangle_topology = topology});
            const std::optional<double> requested_angle =
                mode == ctex::paint::PolygonSelectionMode::connected_by_angle
                    ? std::optional<double>{descriptor->maximum_angle_degrees}
                    : std::nullopt;
            publish_paint_selection(selection, requested_angle, *out_info, outputs);
        } catch (const std::invalid_argument& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL,
                           error.what());
        }
    });
}

extern "C" ctex_result ctex_paint_resolve_stencil_mask(
    const ctex_paint_stencil_descriptor* descriptor, ctex_paint_stencil_info* out_info,
    double* mask_values, std::size_t mask_value_capacity) {
    return call_boundary("ctex_paint_resolve_stencil_mask", [&] {
        if (descriptor == nullptr || out_info == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           descriptor == nullptr ? "descriptor=null" : "out_info=null");
        }
        validate_structure_size(descriptor->size, CTEX_PAINT_STENCIL_DESCRIPTOR_V1_SIZE,
                                CTEX_PAINT_STENCIL_DESCRIPTOR_CURRENT_SIZE, "descriptor.size");
        validate_structure_size(out_info->size, CTEX_PAINT_STENCIL_INFO_V1_SIZE,
                                CTEX_PAINT_STENCIL_INFO_CURRENT_SIZE, "out_info.size");
        const std::size_t pixel_count = bounded_paint_pixel_count(
            descriptor->width, descriptor->height, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL);
        const std::size_t image_pixel_count = bounded_paint_pixel_count(
            descriptor->image_width, descriptor->image_height, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL);
        try {
            require_paint_tool_array(descriptor->image_opacity, descriptor->image_opacity_count,
                                     "image_opacity");
            if (descriptor->image_opacity_count != image_pixel_count) {
                throw std::invalid_argument(
                    "stencil image opacity count does not match its dimensions");
            }
            const auto positions = paint_stencil_screen_positions(*descriptor, pixel_count);
            const ctex::paint::ToolOpacityImage image{
                .width = descriptor->image_width,
                .height = descriptor->image_height,
                .opacity = {descriptor->image_opacity,
                            descriptor->image_opacity + image_pixel_count},
            };
            const ctex::paint::StencilTransform transform{
                .position = {descriptor->position.x, descriptor->position.y},
                .rotation_radians = descriptor->rotation_radians,
                .scale = {descriptor->scale.x, descriptor->scale.y},
            };
            const ctex::paint::StencilMaskResult result = ctex::paint::resolve_stencil_mask(
                descriptor->width, descriptor->height, positions, image, transform,
                paint_flag(descriptor->inverted, "inverted"));
            *out_info = {
                .size = CTEX_PAINT_STENCIL_INFO_CURRENT_SIZE,
                .resolved_position = {result.resolved_transform.position.x,
                                      result.resolved_transform.position.y},
                .resolved_rotation_radians = result.resolved_transform.rotation_radians,
                .resolved_scale = {result.resolved_transform.scale.x,
                                   result.resolved_transform.scale.y},
                .inverted = result.inverted ? 1U : 0U,
                .position_x_clamped = result.parameter_report
                                          .clamp_for(ctex::paint::stencil_position_x_parameter.name)
                                          .has_value(),
                .position_y_clamped = result.parameter_report
                                          .clamp_for(ctex::paint::stencil_position_y_parameter.name)
                                          .has_value(),
                .rotation_clamped =
                    result.parameter_report.clamp_for(ctex::paint::stencil_rotation_parameter.name)
                        .has_value(),
                .scale_x_clamped =
                    result.parameter_report.clamp_for(ctex::paint::stencil_scale_x_parameter.name)
                        .has_value(),
                .scale_y_clamped =
                    result.parameter_report.clamp_for(ctex::paint::stencil_scale_y_parameter.name)
                        .has_value(),
                .required_mask_value_count = pixel_count,
            };
            validate_output_array(mask_values, mask_value_capacity, pixel_count, "mask_values");
            if (mask_values != nullptr) {
                std::copy(result.values.begin(), result.values.end(), mask_values);
            }
        } catch (const std::invalid_argument& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_PAINT_TOOL,
                           error.what());
        }
    });
}

