extern "C" ctex_result ctex_mesh_get_info(const ctex_mesh* mesh, ctex_mesh_info* out_info) {
    return call_boundary("ctex_mesh_get_info", [&] {
        if (mesh == nullptr || out_info == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           mesh == nullptr ? "mesh=null" : "out_info=null");
        }
        validate_structure_size(out_info->size, CTEX_MESH_INFO_V1_SIZE, CTEX_MESH_INFO_CURRENT_SIZE,
                                "out_info.size");
        const ctex::mesh::MeshDescriptor descriptor = mesh->state->descriptor();
        *out_info = {
            .size = CTEX_MESH_INFO_CURRENT_SIZE,
            .vertex_count = descriptor.positions.size(),
            .triangle_count = descriptor.triangle_indices.size() / 3,
            .uv_set_count = descriptor.uv_sets.size(),
            .partition_count = descriptor.partitions.size(),
            .has_vertex_colors = descriptor.vertex_colors.empty() ? 0U : 1U,
            .revision = mesh->state->mesh_binding().revision(),
        };
    });
}

extern "C" ctex_result ctex_mesh_get_uv_set_names(const ctex_mesh* mesh, char* buffer,
                                                  std::size_t buffer_size,
                                                  std::size_t* out_required_size,
                                                  std::size_t* out_count) {
    return call_boundary("ctex_mesh_get_uv_set_names", [&] {
        if (mesh == nullptr || out_required_size == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           mesh == nullptr ? "mesh=null" : "out_required_size=null");
        }
        std::size_t required_size = 0;
        for (const std::pmr::string& name : mesh->state->uv_names) {
            if (name.size() + 1 > std::numeric_limits<std::size_t>::max() - required_size) {
                throw std::overflow_error("UV-set name buffer size overflow");
            }
            required_size += name.size() + 1;
        }
        *out_required_size = required_size;
        if (out_count != nullptr) {
            *out_count = mesh->state->uv_names.size();
        }
        validate_string_buffer(buffer, buffer_size, required_size);
        if (buffer != nullptr) {
            std::size_t offset = 0;
            for (const std::pmr::string& name : mesh->state->uv_names) {
                std::memcpy(buffer + offset, name.c_str(), name.size() + 1);
                offset += name.size() + 1;
            }
        }
    });
}

extern "C" ctex_result ctex_mesh_analyze_uv_overlaps(const ctex_mesh* mesh, const char* uv_set,
                                                     std::uint32_t partition_index,
                                                     ctex_mesh_uv_overlap_info* out_info,
                                                     std::uint32_t* face_indices,
                                                     std::size_t face_index_capacity) {
    return call_boundary("ctex_mesh_analyze_uv_overlaps", [&] {
        if (mesh == nullptr || uv_set == nullptr || out_info == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           "mesh, uv_set and out_info are required");
        }
        validate_structure_size(out_info->size, CTEX_MESH_UV_OVERLAP_INFO_V1_SIZE,
                                CTEX_MESH_UV_OVERLAP_INFO_CURRENT_SIZE,
                                "mesh UV overlap info size");
        if (partition_index >= mesh->state->partition_views.size()) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_MESH,
                           "UV overlap partition index is outside the mesh partition table");
        }
        try {
            const ctex::mesh::UvOverlapReport report = ctex::mesh::analyze_uv_overlaps(
                mesh->state->mesh_binding().view(), uv_set, partition_index);
            *out_info = {
                .size = CTEX_MESH_UV_OVERLAP_INFO_CURRENT_SIZE,
                .required_face_count = report.face_indices.size(),
                .overlap_pair_count = report.overlap_pair_count,
                .candidate_pair_count = report.candidate_pair_count,
            };
            validate_output_array(face_indices, face_index_capacity, report.face_indices.size(),
                                  "overlapping UV face indices");
            if (face_indices != nullptr) {
                std::copy(report.face_indices.begin(), report.face_indices.end(), face_indices);
            }
        } catch (const std::out_of_range& error) {
            throw_boundary(CTEX_RESULT_MISSING_RESOURCE, CTEX_DIAGNOSTIC_MISSING_UV_SET,
                           error.what());
        }
    });
}

extern "C" ctex_result ctex_mesh_analyze_uv_coverage(const ctex_mesh* mesh, const char* uv_set,
                                                     std::uint32_t partition_index,
                                                     std::uint32_t width, std::uint32_t height,
                                                     ctex_mesh_uv_coverage_info* out_info,
                                                     std::uint32_t* outside_face_indices,
                                                     std::size_t outside_face_index_capacity) {
    return call_boundary("ctex_mesh_analyze_uv_coverage", [&] {
        if (mesh == nullptr || uv_set == nullptr || out_info == nullptr) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_NULL_ARGUMENT,
                           "mesh, uv_set and out_info are required");
        }
        validate_structure_size(out_info->size, CTEX_MESH_UV_COVERAGE_INFO_V1_SIZE,
                                CTEX_MESH_UV_COVERAGE_INFO_CURRENT_SIZE,
                                "mesh UV coverage info size");
        if (partition_index >= mesh->state->partition_views.size()) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_MESH,
                           "UV coverage partition index is outside the mesh partition table");
        }
        try {
            const ctex::mesh::UvCoverageReport report = ctex::mesh::analyze_uv_coverage(
                mesh->state->mesh_binding().view(), uv_set, partition_index,
                {.width = width, .height = height});
            *out_info = {
                .size = CTEX_MESH_UV_COVERAGE_INFO_CURRENT_SIZE,
                .width = width,
                .height = height,
                .selected_face_count = report.selected_face_count,
                .covered_texel_count = report.covered_sample_count,
                .uncovered_texel_count = report.uncovered_sample_count,
                .tested_texel_count = report.tested_sample_count,
                .required_outside_face_count = report.outside_face_indices.size(),
                .uncovered_fraction = report.uncovered_fraction,
            };
            validate_output_array(outside_face_indices, outside_face_index_capacity,
                                  report.outside_face_indices.size(),
                                  "outside unit-square UV face indices");
            if (outside_face_indices != nullptr) {
                std::copy(report.outside_face_indices.begin(), report.outside_face_indices.end(),
                          outside_face_indices);
            }
        } catch (const std::length_error& error) {
            throw_boundary(CTEX_RESULT_OVER_BUDGET, CTEX_DIAGNOSTIC_MESH_LIMIT_EXCEEDED,
                           error.what());
        } catch (const std::invalid_argument& error) {
            throw_boundary(CTEX_RESULT_INVALID_ARGUMENT, CTEX_DIAGNOSTIC_INVALID_MESH,
                           error.what());
        } catch (const std::out_of_range& error) {
            throw_boundary(CTEX_RESULT_MISSING_RESOURCE, CTEX_DIAGNOSTIC_MISSING_UV_SET,
                           error.what());
        }
    });
}

